-- Whisk setup 19: 49 more real recipes: budget and few-ingredient meals, soul food, Depression-era and family recipes,
-- and home cooking from DR Congo, Nigeria, Ghana, Senegal, Kenya, South Africa, Haiti, the Philippines, Peru and more.
-- Safe to run more than once.
-- Generated by scripts/gen-more-recipes.mjs from lib/recipes/more.json. Do not edit by hand.
-- 49 real recipes, each linking to the page it came from.
on conflict (id) do update set title = excluded.title, cuisine = excluded.cuisine, source = excluded.source, url = excluded.url, minutes = excluded.minutes,
  servings = excluded.servings, technique = excluded.technique, prep = excluded.prep, precision_level = excluded.precision_level, step_count = excluded.step_count,
  score = excluded.score, key_canon = excluded.key_canon, data = excluded.data, active = true;
