('deepsouthdish-poor-mans-meal-hot-dogs-potatoes', 'Poor Man''s Meal (Hot Dogs with Potatoes and Onions)', 'Southern', 'Deep South Dish', 'https://deepsouthdish.com/2026/01/poor-mans-meal-of-hot-dogs-with.html', 30, 4, 1, 2, 1, 8, 34, array['potatoes', 'hot dog', 'onion']::text[], '{"title":"Poor Man''s Meal (Hot Dogs with Potatoes and Onions)","cuisine":"Southern","source":"Deep South Dish","url":"https://deepsouthdish.com/2026/01/poor-mans-meal-of-hot-dogs-with.html","minutes":30,"servings":4,"key":["Potatoes","Hot dogs","Onion"],"minor":["Bacon drippings or oil","Salt","Black pepper","Parmesan (optional)"],"amounts":{"Potatoes":"4 medium russet","Hot dogs":"4","Onion":"1 small"},"steps":[["Peel and cut [[4]] medium potatoes into small cubes. Halve and slice [[1]] small onion. Slice [[4]] hot dogs into rounds about 1/4 inch thick.",null],["Heat [[0.25 cup]] bacon drippings or oil in a 10-inch skillet over medium-high heat.",null],["Add the potatoes and onion, season with salt and pepper, and toss so everything is coated in the fat.",null],["Push the potatoes and onion out to the edges of the pan. Put the hot dog slices in the middle and toss them in the fat there.",null],["Pour [[0.25 cup]] water around the edges of the pan. Turn the heat to medium, cover, and let it steam without stirring.",10],["Take off the lid, stir everything together, and turn the heat back up to medium-high.",null],["Cook uncovered, stirring now and then, until the potatoes are soft inside and a little browned.",5],["Spoon into a bowl and top with grated Parmesan if you have it.",null]],"technique":1,"prep":2,"precision":1,"nutrition":{"calories":390,"protein_g":10,"carbs_g":33,"fat_g":25},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"bacon drippings or oil","qty":0.25,"unit":"cup"},{"item":"russet potatoes","qty":4,"unit":"medium","note":"peeled and cubed"},{"item":"onion","qty":1,"unit":"small","note":"halved and sliced"},{"item":"hot dogs","qty":4,"note":"sliced 1/4 inch thick"},{"item":"salt","qty":0.5,"unit":"tsp","note":"to taste"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"to taste"},{"item":"water","qty":0.25,"unit":"cup"},{"item":"grated Parmesan","qty":2,"unit":"tbsp","note":"optional"}]}'::jsonb),
('thenonconsumeradvocate-depression-era-wacky-cake', 'Depression-Era Wacky Cake', 'American', 'The Non-Consumer Advocate', 'https://thenonconsumeradvocate.com/cheap-eats-depression-era-wacky-cake/', 40, 9, 1, 1, 3, 6, 31, array['flour', 'sugar', 'cocoa powder']::text[], '{"title":"Depression-Era Wacky Cake","cuisine":"American","source":"The Non-Consumer Advocate","url":"https://thenonconsumeradvocate.com/cheap-eats-depression-era-wacky-cake/","minutes":40,"servings":9,"key":["Flour","Sugar","Cocoa powder"],"minor":["Baking soda","Salt","Vegetable oil","White vinegar","Vanilla extract"],"amounts":{"Flour":"1 1/2 cups","Sugar":"3/4 cup","Cocoa powder":"1/3 cup unsweetened"},"steps":[["Heat the oven to 350°F.",null],["Put [[1.5 cups]] flour, [[0.75 cup]] sugar, [[0.33 cup]] cocoa powder, [[0.5 tsp]] salt and [[1 tsp]] baking soda straight into an 8x8-inch baking dish. Stir with a fork to mix.",null],["Add [[0.33 cup]] vegetable oil, [[1 tbsp]] white vinegar, [[1 tsp]] vanilla and [[1 cup]] water.",null],["Stir right in the pan until smooth and no dry flour is left in the corners. No eggs, butter or greasing needed.",null],["Bake until a toothpick poked in the middle comes out clean.",30],["Serve warm, dusted with powdered sugar if you like.",null]],"technique":1,"prep":1,"precision":3,"nutrition":{"calories":230,"protein_g":3,"carbs_g":34,"fat_g":9},"video":null,"country":"US","effort_steps":3,"ingredients":[{"item":"all-purpose flour","qty":1.5,"unit":"cup"},{"item":"sugar","qty":0.75,"unit":"cup"},{"item":"unsweetened cocoa powder","qty":0.33,"unit":"cup"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"baking soda","qty":1,"unit":"tsp"},{"item":"vegetable oil","qty":0.33,"unit":"cup"},{"item":"distilled white vinegar","qty":1,"unit":"tbsp"},{"item":"vanilla extract","qty":1,"unit":"tsp"},{"item":"water","qty":1,"unit":"cup"}]}'::jsonb),
('newengland-milk-toast', 'Milk Toast', 'American', 'New England Today (from The Little Women Cookbook)', 'https://newengland.com/food/breakfast-brunch/milk-toast/', 10, 2, 1, 1, 1, 6, 22, array['bread', 'milk']::text[], '{"title":"Milk Toast","cuisine":"American","source":"New England Today (from The Little Women Cookbook)","url":"https://newengland.com/food/breakfast-brunch/milk-toast/","minutes":10,"servings":2,"key":["Bread","Milk"],"minor":["Butter","Salt","Sugar","Ground cinnamon"],"amounts":{"Bread":"4 slices sandwich bread","Milk":"1 cup"},"steps":[["Pour [[1 cup]] milk into a small saucepan and warm it over medium heat until it steams. Do not let it boil.",4],["Stir in a pinch of salt, take the pan off the heat and cover it to keep warm.",null],["Toast [[4 slices]] bread and spread them with butter while hot.",null],["Tear the toast into bite-size pieces and split them between two shallow bowls.",null],["Sprinkle the toast with a little sugar and cinnamon.",null],["Pour the warm milk over the toast and eat right away.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":290,"protein_g":10,"carbs_g":36,"fat_g":12},"video":null,"country":"US","effort_steps":4,"ingredients":[{"item":"whole or 2% milk","qty":1,"unit":"cup"},{"item":"salt","qty":1,"unit":"pinch"},{"item":"sandwich bread","qty":4,"unit":"slice"},{"item":"butter","qty":2,"unit":"tbsp","note":"to taste"},{"item":"sugar","qty":2,"unit":"tsp","note":"to taste"},{"item":"ground cinnamon","qty":0.5,"unit":"tsp","note":"to taste"}]}'::jsonb),
('lanascooking-creamed-chipped-beef', 'Creamed Chipped Beef on Toast (S.O.S.)', 'American', 'Lana''s Cooking', 'https://www.lanascooking.com/creamed-chipped-beef/', 20, 4, 2, 1, 2, 8, 38, array['beef', 'milk', 'flour', 'bread', 'butter']::text[], '{"title":"Creamed Chipped Beef on Toast (S.O.S.)","cuisine":"American","source":"Lana''s Cooking","url":"https://www.lanascooking.com/creamed-chipped-beef/","minutes":20,"servings":4,"key":["Dried chipped beef","Milk","Flour","Bread","Butter"],"minor":["Green onions","Black pepper","Pimiento (optional)","Frozen peas (optional)"],"amounts":{"Dried chipped beef":"2.5 oz jar","Milk":"2 cups","Flour":"4 tbsp","Bread":"8 slices","Butter":"4 tbsp"},"steps":[["Rinse [[2.5 oz]] chipped beef under warm water to take off some salt. Tear it into strips and pat dry on paper towels.",null],["Melt [[4 tbsp]] butter in a medium skillet over medium-high heat.",null],["Add [[2]] sliced green onions and the beef. Cook and stir until the onions soften.",3],["Sprinkle in [[4 tbsp]] flour and keep stirring so it cooks and coats the beef.",3],["Slowly pour in [[2 cups]] milk while stirring the whole time. Bring it to a bubble, then lower the heat and simmer until thick.",5],["Stir in [[0.5 tsp]] black pepper. Taste before adding salt because the beef is already salty.",null],["If using, stir in [[2 tbsp]] diced pimiento and [[0.5 cup]] frozen peas and cook until the peas are hot.",3],["Toast [[8 slices]] bread and spoon the creamed beef over the top.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":445,"protein_g":18,"carbs_g":45,"fat_g":22},"video":null,"country":"US","effort_steps":7,"ingredients":[{"item":"dried chipped beef","qty":2.5,"unit":"oz","note":"torn into strips"},{"item":"butter","qty":4,"unit":"tbsp"},{"item":"green onions","qty":2,"note":"sliced"},{"item":"all-purpose flour","qty":4,"unit":"tbsp"},{"item":"milk","qty":2,"unit":"cup"},{"item":"black pepper","qty":0.5,"unit":"tsp"},{"item":"diced pimiento","qty":2,"unit":"tbsp","note":"optional"},{"item":"frozen green peas","qty":0.5,"unit":"cup","note":"optional"},{"item":"bread","qty":8,"unit":"slice","note":"toasted"}]}'::jsonb),
('gritsandpinecones-southern-hoppin-john', 'Hoppin'' John (Black-Eyed Peas and Rice)', 'Soul Food', 'Grits and Pinecones', 'https://www.gritsandpinecones.com/southern-hoppin-john/', 75, 8, 2, 2, 2, 8, 51, array['peas', 'ham hock', 'rice', 'onion', 'broth']::text[], '{"title":"Hoppin'' John (Black-Eyed Peas and Rice)","cuisine":"Soul Food","source":"Grits and Pinecones","url":"https://www.gritsandpinecones.com/southern-hoppin-john/","minutes":75,"servings":8,"key":["Dried black-eyed peas","Ham hock","Rice","Onion","Chicken stock"],"minor":["Olive oil","Garlic","Red wine vinegar","Red pepper flakes","Salt","Black pepper","Hot sauce"],"amounts":{"Dried black-eyed peas":"1 lb","Ham hock":"1","Rice":"3 cups cooked","Onion":"1 medium yellow","Chicken stock":"3 cups"},"steps":[["The night before, cover [[1 lb]] dried black-eyed peas with cold water by at least an inch and let them soak. In a hurry, boil them for 2 minutes and let them sit covered for an hour instead.",null],["Drain the peas and rinse them well.",null],["Heat [[1 tbsp]] olive oil in a large pot over medium-high heat. Add [[1]] chopped onion and [[1]] ham hock and cook until the onion is soft.",5],["Add [[4 cloves]] chopped garlic and cook for about a minute.",1],["Add the peas, [[3 cups]] chicken stock, [[2 tbsp]] red wine vinegar and a pinch of red pepper flakes. Bring to a boil.",null],["Turn the heat to low, cover, and simmer until the peas are tender.",50],["Season with [[0.5 tsp]] salt and [[0.25 tsp]] black pepper, adding more to taste.",null],["Serve the peas over [[3 cups]] hot cooked rice with hot sauce on the side.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":416,"protein_g":19,"carbs_g":76,"fat_g":4},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"dried black-eyed peas","qty":1,"unit":"lb","note":"soaked overnight"},{"item":"chicken stock","qty":3,"unit":"cup"},{"item":"ham hock","qty":1},{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"yellow onion","qty":1,"unit":"medium","note":"chopped"},{"item":"red wine vinegar","qty":2,"unit":"tbsp"},{"item":"garlic","qty":4,"unit":"clove","note":"finely chopped"},{"item":"crushed red pepper flakes","qty":1,"unit":"pinch"},{"item":"kosher salt","qty":0.5,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp"},{"item":"cooked rice","qty":3,"unit":"cup"}]}'::jsonb),
('cookswithsoul-southern-collard-greens-smoked-turkey', 'Southern Collard Greens with Smoked Turkey', 'Soul Food', 'Cooks with Soul', 'https://cookswithsoul.com/southern-collard-greens-recipe-with-smoked-turkey/', 120, 4, 2, 3, 2, 9, 67, array['collard green', 'smoked turkey leg', 'onion']::text[], '{"title":"Southern Collard Greens with Smoked Turkey","cuisine":"Soul Food","source":"Cooks with Soul","url":"https://cookswithsoul.com/southern-collard-greens-recipe-with-smoked-turkey/","minutes":120,"servings":4,"key":["Collard greens","Smoked turkey legs","Onion"],"minor":["Seasoned salt","Chicken bouillon cubes","Black pepper","Kosher salt","Garlic powder","Onion powder","Red pepper flakes","Worcestershire sauce","Apple cider vinegar"],"amounts":{"Collard greens":"2 bunches","Smoked turkey legs":"2","Onion":"1/2 yellow"},"steps":[["Put [[2]] smoked turkey legs in a large pot and add water until it sits about 2 inches over the meat.",null],["Stir in [[0.5]] finely chopped onion, [[1 tbsp]] seasoned salt, [[2]] bouillon cubes, [[1 tbsp]] black pepper, [[1.5 tsp]] kosher salt, [[1 tsp]] garlic powder, [[1 tsp]] onion powder and [[0.5 tsp]] red pepper flakes.",null],["Add [[1 tbsp]] Worcestershire sauce and [[1.5 tsp]] apple cider vinegar.",null],["Bring to a boil, then lower the heat and simmer until the turkey is tender.",45],["While it simmers, strip the stems from [[2 bunches]] collard greens, chop the leaves, and wash them well in several changes of water until no grit is left.",null],["Lift out the turkey legs. Pull the meat off, put it back in the pot, and throw away the bones.",null],["Add the greens and push them down so they are under the liquid.",null],["Cover, turn the heat to medium-low, and simmer until the greens are soft.",60],["Taste and add more salt or pepper if needed. Serve hot with some of the pot liquor.",null]],"technique":2,"prep":3,"precision":2,"nutrition":{"calories":537,"protein_g":70,"carbs_g":9,"fat_g":24},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"smoked turkey legs","qty":2},{"item":"yellow onion","qty":0.5,"note":"finely chopped"},{"item":"seasoned salt","qty":1,"unit":"tbsp"},{"item":"chicken bouillon cubes","qty":2},{"item":"ground black pepper","qty":1,"unit":"tbsp"},{"item":"kosher salt","qty":1.5,"unit":"tsp"},{"item":"garlic powder","qty":1,"unit":"tsp"},{"item":"onion powder","qty":1,"unit":"tsp"},{"item":"red pepper flakes","qty":0.5,"unit":"tsp"},{"item":"Worcestershire sauce","qty":1,"unit":"tbsp"},{"item":"apple cider vinegar","qty":1.5,"unit":"tsp"},{"item":"collard greens","qty":2,"unit":"bunch","note":"stemmed, chopped and washed"}]}'::jsonb),
('cookswithsoul-salmon-croquettes', 'Old-Fashioned Salmon Croquettes', 'Soul Food', 'Cooks with Soul', 'https://cookswithsoul.com/how-to-make-salmon-croquettes/', 30, 4, 2, 2, 2, 7, 42, array['fish', 'eggs', 'breadcrumb', 'onion', 'bell peppers']::text[], '{"title":"Old-Fashioned Salmon Croquettes","cuisine":"Soul Food","source":"Cooks with Soul","url":"https://cookswithsoul.com/how-to-make-salmon-croquettes/","minutes":30,"servings":4,"key":["Canned salmon","Egg","Breadcrumbs","Onion","Bell pepper"],"minor":["Lemon juice","Soul food seasoning","Lemon pepper","Butter","Vegetable oil"],"amounts":{"Canned salmon":"15 oz can","Egg":"1 large","Breadcrumbs":"1/2 cup","Onion":"1/2 cup diced","Bell pepper":"4 tbsp diced (red and green)"},"steps":[["Drain [[15 oz]] canned salmon into a bowl. Flake it with a fork and pick out the skin and any big bones.",null],["Melt a little butter in a skillet and cook [[0.5 cup]] diced onion and [[4 tbsp]] diced bell pepper until soft.",4],["Add the cooked vegetables, [[0.5 cup]] breadcrumbs, [[1]] egg, [[1 tbsp]] lemon juice, [[1 tbsp]] soul food seasoning and [[1 tsp]] lemon pepper to the salmon. Mix well.",null],["Shape the mixture into [[8]] patties.",null],["Heat [[0.5 cup]] vegetable oil in the same skillet over medium-high heat.",null],["Fry the patties a few at a time until golden brown on both sides, about 3 to 4 minutes per side.",8],["Drain on paper towels and serve warm.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":252,"protein_g":28,"carbs_g":12,"fat_g":10},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"canned salmon","qty":15,"unit":"oz","note":"drained"},{"item":"yellow onion","qty":0.5,"unit":"cup","note":"diced"},{"item":"red bell pepper","qty":2,"unit":"tbsp","note":"finely diced"},{"item":"green bell pepper","qty":2,"unit":"tbsp","note":"finely diced"},{"item":"plain breadcrumbs","qty":0.5,"unit":"cup"},{"item":"egg","qty":1,"unit":"large"},{"item":"lemon juice","qty":1,"unit":"tbsp"},{"item":"soul food seasoning","qty":1,"unit":"tbsp"},{"item":"lemon pepper seasoning","qty":1,"unit":"tsp"},{"item":"butter","qty":1,"unit":"tbsp","note":"for the vegetables"},{"item":"vegetable oil","qty":0.5,"unit":"cup","note":"for frying"}]}'::jsonb),
('grandbaby-cakes-southern-fried-cabbage', 'Southern Fried Cabbage with Bacon', 'Soul Food', 'Grandbaby Cakes', 'https://grandbaby-cakes.com/fried-cabbage/', 40, 6, 1, 2, 1, 6, 34, array['cabbage', 'bacon', 'onion']::text[], '{"title":"Southern Fried Cabbage with Bacon","cuisine":"Soul Food","source":"Grandbaby Cakes","url":"https://grandbaby-cakes.com/fried-cabbage/","minutes":40,"servings":6,"key":["Cabbage","Bacon","Onion"],"minor":["Garlic","Kosher salt","Black pepper","Smoked paprika","Garlic powder","Cayenne (optional)","Sugar","Apple cider vinegar"],"amounts":{"Cabbage":"1 small head (about 2 lb)","Bacon":"4 slices thick-cut","Onion":"1 small yellow"},"steps":[["Cut [[4 slices]] thick-cut bacon into 1/2-inch pieces. Dice [[1]] small onion, chop [[3 cloves]] garlic, and cut [[1]] small head of cabbage into large pieces.",null],["Cook the bacon in a large skillet over medium heat until lightly browned and the fat has melted out.",8],["Add the onion and cook, stirring often, until soft. Add the garlic and cook 1 more minute.",6],["Add the cabbage and keep turning it with tongs as it shrinks down. Turn the heat down a bit if it starts to burn.",null],["Season with [[0.75 tsp]] kosher salt, [[0.5 tsp]] black pepper, [[0.5 tsp]] smoked paprika, [[0.25 tsp]] garlic powder and [[0.25 tsp]] cayenne if you want heat. Cook until wilted but still a little crisp.",8],["Stir in [[1 tbsp]] sugar and [[1 tbsp]] apple cider vinegar and cook 1 more minute. Serve right away.",1]],"technique":1,"prep":2,"precision":1,"nutrition":{"calories":149,"protein_g":5,"carbs_g":12,"fat_g":10},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"thick-cut bacon","qty":4,"unit":"slice","note":"cut into 1/2-inch pieces"},{"item":"yellow onion","qty":1,"unit":"small","note":"diced"},{"item":"garlic","qty":3,"unit":"clove","note":"roughly chopped"},{"item":"green cabbage","qty":1,"unit":"small head","note":"about 2 lb, cut into large pieces"},{"item":"kosher salt","qty":0.75,"unit":"tsp"},{"item":"black pepper","qty":0.5,"unit":"tsp"},{"item":"smoked paprika","qty":0.5,"unit":"tsp"},{"item":"garlic powder","qty":0.25,"unit":"tsp"},{"item":"cayenne pepper","qty":0.25,"unit":"tsp","note":"optional"},{"item":"sugar","qty":1,"unit":"tbsp"},{"item":"apple cider vinegar","qty":1,"unit":"tbsp"}]}'::jsonb),
('andy-cooks-peanut-butter-ramen', 'Peanut Butter Ramen with Egg', 'Korean-American', 'Andy Cooks', 'https://www.andy-cooks.com/blogs/recipes/peanut-butter-ramen', 7, 1, 1, 1, 1, 6, 23, array['ramen noodle', 'butter', 'eggs', 'scallions']::text[], '{"title":"Peanut Butter Ramen with Egg","cuisine":"Korean-American","source":"Andy Cooks","url":"https://www.andy-cooks.com/blogs/recipes/peanut-butter-ramen","minutes":7,"servings":1,"key":["Ramen noodles","Peanut butter","Eggs","Green onion"],"minor":["Chili crisp","Cooked chicken (optional)"],"amounts":{"Ramen noodles":"1 packet (about 130 g) with seasoning","Peanut butter":"1 tbsp crunchy","Eggs":"2","Green onion":"1"},"steps":[["Slice [[1]] green onion, keeping the white and green parts apart. Beat [[2]] eggs in a cup.",null],["Bring [[2 cups]] water to a simmer in a small pot. This is less water than the packet says, so the broth is richer.",3],["Stir in all the seasoning packets from [[1]] ramen packet and [[1 tbsp]] peanut butter until it melts into the broth.",null],["Add the noodles and cook about 45 seconds, then gently pull them apart. Stir in the white parts of the onion and [[0.5 cup]] shredded cooked chicken if you have it.",1],["Slowly pour the beaten eggs into the pot in a thin stream while stirring, so they form silky ribbons. Take the pot off the heat.",null],["Stir in half the green onion tops, pour into a bowl, and finish with the rest of the green onion and a spoon of chili crisp. Eat right away.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":720,"protein_g":30,"carbs_g":80,"fat_g":32},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"water","qty":2,"unit":"cup","note":"about 500 ml"},{"item":"instant ramen","qty":1,"unit":"packet","note":"about 130 g, with seasoning"},{"item":"crunchy peanut butter","qty":1,"unit":"tbsp"},{"item":"eggs","qty":2,"unit":"large","note":"beaten"},{"item":"green onion","qty":1,"note":"sliced, white and green separated"},{"item":"cooked chicken","qty":0.5,"unit":"cup","note":"shredded, optional"},{"item":"chili crisp","qty":1,"unit":"tsp","note":"to serve"}]}'::jsonb),
('onolicioushawaii-spam-fried-rice', 'Spam Fried Rice', 'Hawaiian', 'Onolicious Hawaii', 'https://onolicioushawaii.com/spam-fried-rice/', 15, 3, 2, 1, 1, 6, 33, array['rice', 'spam', 'eggs', 'garlic']::text[], '{"title":"Spam Fried Rice","cuisine":"Hawaiian","source":"Onolicious Hawaii","url":"https://onolicioushawaii.com/spam-fried-rice/","minutes":15,"servings":3,"key":["Rice","Spam","Eggs","Garlic"],"minor":["Maggi seasoning or soy sauce","Sesame oil (optional)","Oil"],"amounts":{"Rice":"5-6 cups cooked, cold","Spam":"1 can (12 oz)","Eggs":"4-5","Garlic":"1 head"},"steps":[["Dice [[1 can]] Spam into small cubes and mince [[1 head]] garlic.",null],["Fry the Spam in a large dry pan over medium-high heat until a little crispy. Move it to a bowl.",5],["Add a little oil to the pan and cook the garlic until golden.",1],["Add [[5 cups]] cold cooked rice and stir to break up clumps. Press it flat and let it sit so the bottom gets crispy.",4],["Push the rice to the sides of the pan. Crack [[4]] eggs into the empty middle, drizzle with half of [[1 tbsp]] Maggi seasoning, and scramble lightly for about a minute.",1],["Add the Spam back and mix everything together. Season with the rest of the Maggi and [[1 tbsp]] sesame oil if using, then serve.",null]],"technique":2,"prep":1,"precision":1,"nutrition":{"calories":780,"protein_g":30,"carbs_g":90,"fat_g":32},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"cooked rice","qty":5,"unit":"cup","note":"cold leftover rice works best"},{"item":"Spam","qty":1,"unit":"can","note":"12 oz, diced"},{"item":"eggs","qty":4,"unit":"large"},{"item":"garlic","qty":1,"unit":"head","note":"minced"},{"item":"Maggi seasoning or soy sauce","qty":1,"unit":"tbsp"},{"item":"sesame oil","qty":1,"unit":"tbsp","note":"optional"},{"item":"cooking oil","qty":1,"unit":"tbsp"}]}'::jsonb),
('budgetbytes-make-ahead-bean-and-cheese-burritos', 'Make-Ahead Bean and Cheese Burritos', 'Mexican-American', 'Budget Bytes', 'https://www.budgetbytes.com/make-ahead-bean-and-cheese-burritos/', 50, 8, 2, 2, 2, 8, 47, array['tortillas', 'black beans', 'cheddar', 'rice', 'taco sauce']::text[], '{"title":"Make-Ahead Bean and Cheese Burritos","cuisine":"Mexican-American","source":"Budget Bytes","url":"https://www.budgetbytes.com/make-ahead-bean-and-cheese-burritos/","minutes":50,"servings":8,"key":["Flour tortillas","Black beans","Cheddar cheese","Rice","Taco sauce"],"minor":["Cooking oil","Garlic","Chili powder","Ground cumin","Dried oregano","Salt","Green onions"],"amounts":{"Flour tortillas":"8 large","Black beans":"2 cans (15 oz)","Cheddar cheese":"2 cups shredded","Rice":"1 cup uncooked long-grain","Taco sauce":"1/2 cup"},"steps":[["Heat [[1 tbsp]] oil and [[1 clove]] minced garlic in a saucepan over medium heat for about a minute.",1],["Stir in [[1 tsp]] chili powder, [[0.25 tsp]] cumin, [[0.25 tsp]] oregano and [[1 cup]] uncooked rice. Keep stirring for 2 minutes.",2],["Add [[1.5 cups]] water and [[0.5 tsp]] salt. Cover and bring to a boil, then turn the heat down and simmer.",15],["Turn off the heat and let the rice sit, still covered, then fluff with a fork.",5],["While the rice cooks, rinse and drain [[2 cans]] black beans and slice [[2]] green onions.",null],["Warm [[8]] large tortillas under a damp paper towel in the microwave for about 30 seconds so they bend without cracking.",null],["On each tortilla, add about 1/3 cup rice, 1/3 cup beans, 1 tbsp of the [[0.5 cup]] taco sauce, 1/4 cup of the [[2 cups]] cheddar, and some green onion.",null],["Fold in the sides and roll up tightly. Eat now, or wrap each one and freeze for later.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":348,"protein_g":16,"carbs_g":44,"fat_g":13},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"cooking oil","qty":1,"unit":"tbsp"},{"item":"garlic","qty":1,"unit":"clove","note":"minced"},{"item":"chili powder","qty":1,"unit":"tsp"},{"item":"ground cumin","qty":0.25,"unit":"tsp"},{"item":"dried oregano","qty":0.25,"unit":"tsp"},{"item":"long-grain white rice","qty":1,"unit":"cup"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"water","qty":1.5,"unit":"cup"},{"item":"black beans","qty":2,"unit":"can","note":"15 oz each, rinsed and drained"},{"item":"shredded cheddar cheese","qty":2,"unit":"cup"},{"item":"green onions","qty":2,"note":"sliced"},{"item":"taco sauce","qty":0.5,"unit":"cup"},{"item":"large flour tortillas","qty":8}]}'::jsonb),
('insanelygoodrecipes-fried-bologna-sandwich', 'Fried Bologna Sandwich', 'Southern', 'Insanely Good Recipes', 'https://insanelygoodrecipes.com/fried-bologna-sandwich/', 10, 1, 1, 1, 1, 5, 22, array['bologna', 'bread', 'american cheese']::text[], '{"title":"Fried Bologna Sandwich","cuisine":"Southern","source":"Insanely Good Recipes","url":"https://insanelygoodrecipes.com/fried-bologna-sandwich/","minutes":10,"servings":1,"key":["Bologna","Bread","American cheese"],"minor":["Oil or butter","Mustard"],"amounts":{"Bologna":"1-2 slices","Bread":"2 slices white","American cheese":"1 slice"},"steps":[["Heat a small splash of oil or butter in a skillet over medium-high heat.",null],["Cut [[4]] small slits around the edge of [[2 slices]] bologna so it lies flat instead of puffing up into a dome.",null],["Fry the bologna until browned and as crispy as you like, then flip it. Toast the bread now if you want.",3],["Lay [[1 slice]] American cheese on the bologna while it is still in the pan so it melts.",1],["Spread [[1 tbsp]] mustard on [[2 slices]] bread, add the bologna and cheese, and serve.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":420,"protein_g":15,"carbs_g":28,"fat_g":27},"video":null,"country":"US","effort_steps":4,"ingredients":[{"item":"white bread","qty":2,"unit":"slice"},{"item":"bologna","qty":2,"unit":"slice"},{"item":"oil or butter","qty":0.5,"unit":"tsp"},{"item":"American cheese","qty":1,"unit":"slice"},{"item":"mustard","qty":1,"unit":"tbsp"}]}'::jsonb),
('dinnerin321-old-fashioned-tuna-noodle-casserole', 'Old-Fashioned Tuna Noodle Casserole', 'American', 'Dinner in 321', 'https://www.dinnerin321.com/old-fashioned-tuna-noodle-casserole/', 45, 8, 1, 2, 2, 8, 41, array['noodles', 'tuna', 'cream', 'cheddar', 'peas', 'milk', 'ritz cracker']::text[], '{"title":"Old-Fashioned Tuna Noodle Casserole","cuisine":"American","source":"Dinner in 321","url":"https://www.dinnerin321.com/old-fashioned-tuna-noodle-casserole/","minutes":45,"servings":8,"key":["Egg noodles","Canned tuna","Cream of mushroom soup","Cheddar cheese","Frozen peas","Milk","Ritz crackers"],"minor":["Garlic powder","Onion powder","Seasoning salt","Butter"],"amounts":{"Egg noodles":"12 oz wide","Canned tuna":"10 oz in water","Cream of mushroom soup":"2 cans (10.5 oz)","Cheddar cheese":"2 cups shredded","Frozen peas":"1 cup","Milk":"1 cup","Ritz crackers":"1 cup crumbs"},"steps":[["Heat the oven to 375°F and grease a 9x13-inch baking dish.",null],["Boil [[12 oz]] egg noodles until just tender, then drain.",8],["In a large bowl, whisk [[2 cans]] cream of mushroom soup with [[1 cup]] milk until smooth.",null],["Stir in [[1 cup]] thawed peas, [[10 oz]] drained and flaked tuna, [[1.5 cups]] of the cheddar, [[1 tsp]] garlic powder, [[1 tsp]] onion powder and [[1 tsp]] seasoning salt.",null],["Gently fold in the noodles until coated, then spread everything in the baking dish.",null],["Sprinkle the remaining [[0.5 cup]] cheddar on top.",null],["Mix [[1 cup]] cracker crumbs with [[4 tbsp]] melted butter and scatter over the cheese.",null],["Bake until golden on top and bubbling at the edges.",28]],"technique":1,"prep":2,"precision":2,"nutrition":{"calories":365,"protein_g":24,"carbs_g":41,"fat_g":11},"video":null,"country":"US","effort_steps":7,"ingredients":[{"item":"wide egg noodles","qty":12,"unit":"oz"},{"item":"condensed cream of mushroom soup","qty":2,"unit":"can","note":"10.5 oz each"},{"item":"milk","qty":1,"unit":"cup"},{"item":"frozen peas","qty":1,"unit":"cup","note":"thawed"},{"item":"canned tuna in water","qty":10,"unit":"oz","note":"drained and flaked"},{"item":"shredded cheddar cheese","qty":2,"unit":"cup","note":"divided"},{"item":"garlic powder","qty":1,"unit":"tsp"},{"item":"onion powder","qty":1,"unit":"tsp"},{"item":"seasoning salt","qty":1,"unit":"tsp"},{"item":"buttery round cracker crumbs","qty":1,"unit":"cup"},{"item":"salted butter","qty":4,"unit":"tbsp","note":"melted"}]}'::jsonb),
('pocketchangegourmet-old-fashioned-homemade-pancakes', 'Old-Fashioned Pancakes from Scratch', 'American', 'Pocket Change Gourmet', 'https://pocketchangegourmet.com/old-fashioned-homemade-pancakes/', 25, 3, 2, 1, 3, 7, 39, array['flour', 'milk', 'eggs', 'butter']::text[], '{"title":"Old-Fashioned Pancakes from Scratch","cuisine":"American","source":"Pocket Change Gourmet","url":"https://pocketchangegourmet.com/old-fashioned-homemade-pancakes/","minutes":25,"servings":3,"key":["Flour","Milk","Egg","Butter"],"minor":["Sugar","Baking powder","Salt","Maple syrup"],"amounts":{"Flour":"1 cup","Milk":"3/4 cup","Egg":"1","Butter":"4 tbsp, melted"},"steps":[["In a large bowl, whisk [[1 cup]] flour, [[1 tbsp]] sugar, [[3 tsp]] baking powder and [[0.5 tsp]] salt.",null],["In another bowl, mix [[1]] egg, [[0.75 cup]] milk and [[4 tbsp]] melted butter.",null],["Pour the wet mix into the dry mix and stir only until no dry flour shows. A few lumps are fine.",null],["Let the batter rest while you heat a griddle or skillet over medium heat and grease it lightly.",10],["Pour about [[0.25 cup]] batter per pancake onto the hot pan.",null],["When bubbles on top pop and leave open holes, flip the pancake.",3],["Cook the second side until golden brown, then serve warm with butter and syrup.",3]],"technique":2,"prep":1,"precision":3,"nutrition":{"calories":340,"protein_g":8,"carbs_g":38,"fat_g":18},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"all-purpose flour","qty":1,"unit":"cup"},{"item":"sugar","qty":1,"unit":"tbsp"},{"item":"baking powder","qty":3,"unit":"tsp"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"egg","qty":1,"unit":"large"},{"item":"milk","qty":0.75,"unit":"cup"},{"item":"butter","qty":4,"unit":"tbsp","note":"melted"}]}'::jsonb),
('southern-bytes-southern-buttermilk-cornbread', 'Southern Buttermilk Skillet Cornbread', 'Southern', 'Southern Bytes', 'https://southern-bytes.com/southern-cornbread/', 35, 8, 2, 1, 3, 8, 42, array['cornmeal', 'flour', 'butter', 'eggs']::text[], '{"title":"Southern Buttermilk Skillet Cornbread","cuisine":"Southern","source":"Southern Bytes","url":"https://southern-bytes.com/southern-cornbread/","minutes":35,"servings":8,"key":["Cornmeal","Flour","Buttermilk","Eggs","Butter"],"minor":["Baking powder","Baking soda","Kosher salt","Bacon grease (optional)"],"amounts":{"Cornmeal":"3/4 cup yellow","Flour":"3/4 cup","Buttermilk":"1 cup","Eggs":"2","Butter":"6 tbsp"},"steps":[["Put a 10-inch cast iron skillet in the oven and heat the oven to 425°F. After a few minutes, add [[1 tbsp]] butter or bacon grease to the hot skillet and swirl it around.",null],["Melt [[5 tbsp]] butter and let it cool a little.",null],["In a small bowl, whisk [[0.75 cup]] flour, [[0.75 cup]] cornmeal, [[1.5 tsp]] baking powder, [[0.5 tsp]] baking soda and [[0.5 tsp]] kosher salt.",null],["In a large bowl, whisk [[1 cup]] buttermilk and [[2]] eggs, then whisk in the melted butter.",null],["Add the dry mix to the wet mix and stir just until combined.",null],["Carefully take the hot skillet out of the oven and pour in the batter. The edges should sizzle.",null],["Bake until golden and a toothpick in the center comes out clean.",20],["Let it cool about 10 minutes before slicing.",10]],"technique":2,"prep":1,"precision":3,"nutrition":{"calories":213,"protein_g":5,"carbs_g":22,"fat_g":12},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"butter or bacon grease","qty":1,"unit":"tbsp","note":"for the skillet"},{"item":"butter","qty":5,"unit":"tbsp","note":"melted and cooled"},{"item":"all-purpose flour","qty":0.75,"unit":"cup"},{"item":"yellow cornmeal","qty":0.75,"unit":"cup"},{"item":"baking powder","qty":1.5,"unit":"tsp"},{"item":"baking soda","qty":0.5,"unit":"tsp"},{"item":"kosher salt","qty":0.5,"unit":"tsp"},{"item":"buttermilk","qty":1,"unit":"cup"},{"item":"eggs","qty":2,"unit":"large"}]}'::jsonb),
('southernplate-hot-water-cornbread', 'Hot Water Cornbread', 'Soul Food', 'Southern Plate', 'https://www.southernplate.com/hot-water-cornbread-recipe/', 15, 4, 2, 1, 1, 6, 31, array['selfrising cornmeal', 'oil']::text[], '{"title":"Hot Water Cornbread","cuisine":"Soul Food","source":"Southern Plate","url":"https://www.southernplate.com/hot-water-cornbread-recipe/","minutes":15,"servings":4,"key":["Self-rising cornmeal","Vegetable oil"],"minor":["Garlic powder (optional)","Black pepper (optional)"],"amounts":{"Self-rising cornmeal":"2 cups","Vegetable oil":"about 1/4 inch deep in the skillet"},"steps":[["Put [[2 cups]] self-rising cornmeal in a mixing bowl.",null],["Pour in [[1 cup]] boiling water and stir until smooth. Add a spoonful more water if it is too stiff, or a little more cornmeal if it is runny.",null],["Heat about 1/4 inch of vegetable oil in a large cast iron skillet over medium-high heat.",null],["Drop spoonfuls of batter into the hot oil and press each one flat with the back of the spoon.",null],["Fry until the bottom is browned, then flip and brown the other side.",5],["Drain on paper towels and serve warm.",null]],"technique":2,"prep":1,"precision":1,"nutrition":{"calories":290,"protein_g":5,"carbs_g":46,"fat_g":10},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"self-rising cornmeal","qty":2,"unit":"cup"},{"item":"boiling water","qty":1,"unit":"cup"},{"item":"vegetable oil","qty":0.5,"unit":"cup","note":"about 1/4 inch deep, for frying"}]}'::jsonb),
('blackpeoplesrecipes-southern-pinto-beans', 'Southern Pinto Beans with Ham Hock', 'Soul Food', 'Black People''s Recipes', 'https://blackpeoplesrecipes.com/southern-pinto-beans/', 180, 10, 1, 2, 1, 6, 52, array['pinto bean', 'ham hock', 'broth', 'onion']::text[], '{"title":"Southern Pinto Beans with Ham Hock","cuisine":"Soul Food","source":"Black People''s Recipes","url":"https://blackpeoplesrecipes.com/southern-pinto-beans/","minutes":180,"servings":10,"key":["Dried pinto beans","Ham hocks","Chicken broth","Onion"],"minor":["Olive oil","Garlic","Creole seasoning","Bay leaf"],"amounts":{"Dried pinto beans":"1 lb","Ham hocks":"1-1 1/2 lb","Chicken broth":"5-6 cups","Onion":"1 cup chopped"},"steps":[["Rinse [[1 lb]] dried pinto beans. Bring a big pot of water to a boil, take it off the heat, add the beans and let them soak for an hour. Drain.",60],["Heat [[1 tsp]] olive oil in a large pot over medium-high heat. Cook [[1 cup]] chopped onion and [[3 cloves]] minced garlic until soft and fragrant.",4],["Add [[6 cups]] chicken broth, the beans, [[1.5 lb]] ham hocks, [[1 tsp]] Creole seasoning and [[1]] bay leaf. The beans should be fully covered.",null],["Cover, turn the heat to medium-low, and simmer until the beans mash easily with a spoon. Add water if the level drops below the beans.",120],["Take out the bay leaf and ham hocks. Shred any meat from the hocks and stir it back into the beans.",null],["Taste and adjust the seasoning, then serve with cornbread.",null]],"technique":1,"prep":2,"precision":1,"nutrition":{"calories":314,"protein_g":13,"carbs_g":11,"fat_g":23},"video":null,"country":"US","effort_steps":4,"ingredients":[{"item":"olive oil","qty":1,"unit":"tsp"},{"item":"white onion","qty":1,"unit":"cup","note":"chopped"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"chicken broth","qty":6,"unit":"cup","note":"or water, enough to cover"},{"item":"dried pinto beans","qty":1,"unit":"lb","note":"rinsed"},{"item":"ham hocks","qty":1.5,"unit":"lb"},{"item":"Creole seasoning","qty":1,"unit":"tsp"},{"item":"bay leaf","qty":1}]}'::jsonb),
('copykat-fried-cornmeal-mush', 'Fried Cornmeal Mush', 'American', 'CopyKat Recipes', 'https://copykat.com/fried-corn-meal-mush-a-childhood-favorite-that-you-can-make-anytime/', 70, 10, 2, 1, 2, 8, 49, array['cornmeal', 'oil']::text[], '{"title":"Fried Cornmeal Mush","cuisine":"American","source":"CopyKat Recipes","url":"https://copykat.com/fried-corn-meal-mush-a-childhood-favorite-that-you-can-make-anytime/","minutes":70,"servings":10,"key":["Cornmeal","Vegetable oil"],"minor":["Salt","Sugar","Butter","Syrup"],"amounts":{"Cornmeal":"1 cup yellow","Vegetable oil":"enough to coat the skillet"},"steps":[["Bring [[2.75 cups]] water to a boil in a saucepan over high heat.",null],["In a bowl, stir [[1 cup]] cornmeal with [[1 cup]] cold water, [[1 tsp]] salt and [[1 tsp]] sugar. Mixing it with cold water first keeps it from going lumpy.",null],["Slowly pour the cornmeal mixture into the boiling water while stirring the whole time.",null],["Turn the heat to medium-high and stir until it thickens. Then turn it to low, cover, and cook, stirring often.",5],["Pour the mush into a loaf pan, let it cool, then refrigerate overnight or until completely firm.",null],["Turn the firm loaf out of the pan and cut it into slices about 1/4 to 1/2 inch thick.",null],["Coat a skillet with oil and heat over medium until it shimmers. Fry the slices slowly until browned on both sides.",10],["Serve hot with butter and syrup.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":95,"protein_g":1,"carbs_g":11,"fat_g":5},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"water","qty":2.75,"unit":"cup","note":"for boiling"},{"item":"yellow cornmeal","qty":1,"unit":"cup"},{"item":"cold water","qty":1,"unit":"cup"},{"item":"salt","qty":1,"unit":"tsp"},{"item":"sugar","qty":1,"unit":"tsp"},{"item":"vegetable oil","qty":2,"unit":"tbsp","note":"to coat the skillet"}]}'::jsonb),
('loavesanddishes-southern-fried-potatoes-and-onions', 'Southern Fried Potatoes and Onions', 'Southern', 'Loaves and Dishes', 'https://loavesanddishes.net/southern-fried-potatoes-and-onions', 40, 4, 2, 2, 1, 7, 42, array['potatoes', 'onion']::text[], '{"title":"Southern Fried Potatoes and Onions","cuisine":"Southern","source":"Loaves and Dishes","url":"https://loavesanddishes.net/southern-fried-potatoes-and-onions","minutes":40,"servings":4,"key":["Potatoes","Onion"],"minor":["Peanut oil","Butter","Salt","Black pepper","Paprika (optional)"],"amounts":{"Potatoes":"1 lb red or russet","Onion":"1/2 medium sweet onion"},"steps":[["Stir [[2 tbsp]] salt into [[4 cups]] water in a bowl.",null],["Cut [[1 lb]] potatoes into even cubes or chips and drop them into the salt water as you go. Let them soak 5 minutes.",5],["Cut [[0.5]] sweet onion into chunks a little bigger than the potatoes.",null],["Heat a 9-inch cast iron skillet over medium heat with enough peanut oil to cover the bottom plus [[2 tbsp]] butter, until the oil shimmers.",null],["Drain the potatoes and pat them very dry with paper towels so the oil does not spatter.",null],["Add the potatoes and onion in a single layer, cooking in batches if needed. Cook about 4 minutes, then flip and cook another 2 to 4 minutes until golden and tender.",8],["Drain on paper towels and season with salt and pepper while still hot. Sprinkle with paprika if you like.",null]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":160,"protein_g":2,"carbs_g":24,"fat_g":7},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"peanut oil","qty":2,"unit":"tbsp","note":"enough to coat the pan"},{"item":"unsalted butter","qty":2,"unit":"tbsp"},{"item":"red or russet potatoes","qty":1,"unit":"lb"},{"item":"water","qty":4,"unit":"cup","note":"for soaking"},{"item":"salt","qty":2,"unit":"tbsp","note":"for the soaking water, plus more to taste"},{"item":"sweet onion","qty":0.5,"unit":"medium"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"to taste"}]}'::jsonb),
('tastesbetterfromscratch-hamburger-gravy', 'Hamburger Gravy', 'American', 'Tastes Better From Scratch', 'https://tastesbetterfromscratch.com/hamburger-gravy', 20, 4, 1, 1, 2, 6, 28, array['beef', 'milk', 'flour', 'onion']::text[], '{"title":"Hamburger Gravy","cuisine":"American","source":"Tastes Better From Scratch","url":"https://tastesbetterfromscratch.com/hamburger-gravy","minutes":20,"servings":4,"key":["Ground beef","Milk","Flour","Onion"],"minor":["Garlic","Butter","Beef bouillon","Ground sage","Dried thyme","Salt","Black pepper","Red pepper flakes (optional)"],"amounts":{"Ground beef":"1 lb lean","Milk":"2 1/2 cups","Flour":"3 tbsp","Onion":"1/3 cup chopped"},"steps":[["Brown [[1 lb]] ground beef in a deep skillet over medium-high heat, breaking it into small crumbles. Pour off most of the grease but leave a little.",7],["Add [[0.33 cup]] chopped onion and [[2 cloves]] minced garlic and cook until soft.",3],["Stir in [[1 tbsp]] butter and [[3 tbsp]] flour until all the meat is coated.",null],["Pour in [[2.5 cups]] milk and add [[2 tsp]] beef bouillon, [[0.125 tsp]] sage, [[0.125 tsp]] thyme, and salt and pepper.",null],["Cook, stirring often, until the gravy thickens.",7],["Taste and adjust the seasoning. Serve over mashed potatoes, rice, toast, biscuits or noodles.",null]],"technique":1,"prep":1,"precision":2,"nutrition":{"calories":346,"protein_g":29,"carbs_g":13,"fat_g":19},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"lean ground beef","qty":1,"unit":"lb"},{"item":"onion","qty":0.33,"unit":"cup","note":"chopped"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"butter","qty":1,"unit":"tbsp"},{"item":"all-purpose flour","qty":3,"unit":"tbsp"},{"item":"beef bouillon paste","qty":2,"unit":"tsp","note":"or 2 bouillon cubes"},{"item":"milk","qty":2.5,"unit":"cup"},{"item":"ground sage","qty":0.125,"unit":"tsp"},{"item":"dried thyme","qty":0.125,"unit":"tsp"},{"item":"salt","qty":0.5,"unit":"tsp","note":"to taste"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"to taste"}]}'::jsonb),
('grit-mashed-potato-pancakes', 'Potato Pancakes from Leftover Mashed Potatoes', 'American', 'GRIT Magazine', 'https://www.grit.com/departments/mashed-potato-pancakes-recipe/', 30, 4, 2, 1, 1, 6, 35, array['potatoes', 'eggs', 'flour', 'cabbage', 'carrots']::text[], '{"title":"Potato Pancakes from Leftover Mashed Potatoes","cuisine":"American","source":"GRIT Magazine","url":"https://www.grit.com/departments/mashed-potato-pancakes-recipe/","minutes":30,"servings":4,"key":["Mashed potatoes","Eggs","Flour","Cooked cabbage","Cooked carrots"],"minor":["Dried thyme","Garlic powder","Hot sauce","Salt","Black pepper","Butter"],"amounts":{"Mashed potatoes":"3 cups, chilled","Eggs":"2","Flour":"1/4 cup","Cooked cabbage":"2 cups chopped (or other leftover vegetable)","Cooked carrots":"1/2 cup chopped"},"steps":[["In a large bowl, mix [[3 cups]] cold mashed potatoes, [[2 cups]] chopped cooked cabbage, [[0.5 cup]] chopped cooked carrots, [[0.25 cup]] flour and [[2]] beaten eggs.",null],["Stir in [[0.5 tsp]] thyme, [[0.25 tsp]] garlic powder, a dash of hot sauce, and salt and pepper to taste.",null],["Melt [[1 tbsp]] butter in a large nonstick skillet over medium heat.",null],["Scoop about 1/4 cup of the mix per pancake into the pan and flatten each into a round about 1/4 inch thick.",null],["Cook until golden on the bottom, add a little more butter, then flip and cook the other side.",8],["Repeat with the rest of the mix, adding butter as needed. Serve with sour cream or applesauce.",null]],"technique":2,"prep":1,"precision":1,"nutrition":{"calories":290,"protein_g":8,"carbs_g":38,"fat_g":12},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"mashed potatoes","qty":3,"unit":"cup","note":"chilled leftovers"},{"item":"cooked cabbage","qty":2,"unit":"cup","note":"chopped, or other leftover vegetable"},{"item":"cooked carrots","qty":0.5,"unit":"cup","note":"finely chopped"},{"item":"all-purpose flour","qty":0.25,"unit":"cup"},{"item":"eggs","qty":2,"unit":"large","note":"beaten"},{"item":"dried thyme","qty":0.5,"unit":"tsp"},{"item":"garlic powder","qty":0.25,"unit":"tsp"},{"item":"hot pepper sauce","qty":2,"unit":"dash"},{"item":"salt","qty":0.5,"unit":"tsp","note":"to taste"},{"item":"butter","qty":3,"unit":"tbsp","note":"divided"}]}'::jsonb),
('foxeslovelemons-old-fashioned-ham-and-bean-soup', 'Old-Fashioned Ham and Bean Soup', 'American', 'Foxes Love Lemons', 'https://foxeslovelemons.com/wprm_print/ham-bean-soup-recipe', 115, 8, 1, 2, 1, 6, 51, array['navy bean', 'ham bone', 'ham', 'carrots', 'celery', 'onion']::text[], '{"title":"Old-Fashioned Ham and Bean Soup","cuisine":"American","source":"Foxes Love Lemons","url":"https://foxeslovelemons.com/wprm_print/ham-bean-soup-recipe","minutes":115,"servings":8,"key":["Dried navy beans","Ham bone","Ham","Carrots","Celery","Onion"],"minor":["Butter","Garlic","Thyme","Bay leaf","Kosher salt","Black pepper"],"amounts":{"Dried navy beans":"2 cups, soaked overnight","Ham bone":"1 leftover","Ham":"1 1/2 cups chopped","Carrots":"2 large","Celery":"2 stalks","Onion":"1/2 large yellow"},"steps":[["The night before, cover [[2 cups]] dried navy beans with cold water by a couple of inches and soak. Drain in the morning.",null],["Melt [[2 tbsp]] butter in a large pot over medium heat. Add [[3 cloves]] minced garlic, [[2]] chopped celery stalks, [[2]] chopped carrots and [[0.5]] chopped onion. Cook until soft.",5],["Add [[1 tsp]] dried thyme, [[1]] bay leaf, [[1]] ham bone, [[8 cups]] cold water, the beans and [[1.5 cups]] chopped ham.",null],["Bring to a boil, then cover, turn the heat to medium-low, and simmer, stirring now and then, until the beans are very soft but still whole.",90],["Take out the ham bone and bay leaf. Add a little water if the soup is too thick.",null],["Taste, then season with salt and pepper. The ham may be salty enough already.",null]],"technique":1,"prep":2,"precision":1,"nutrition":{"calories":245,"protein_g":16,"carbs_g":35,"fat_g":5},"video":null,"country":"US","effort_steps":4,"ingredients":[{"item":"unsalted butter","qty":2,"unit":"tbsp"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"celery","qty":2,"unit":"stalk","note":"chopped"},{"item":"carrots","qty":2,"unit":"large","note":"chopped"},{"item":"yellow onion","qty":0.5,"unit":"large","note":"chopped"},{"item":"dried thyme","qty":1,"unit":"tsp","note":"or 3 fresh sprigs"},{"item":"bay leaf","qty":1},{"item":"ham bone","qty":1},{"item":"cold water","qty":8,"unit":"cup"},{"item":"dried navy beans","qty":2,"unit":"cup","note":"soaked overnight and drained"},{"item":"cooked ham","qty":1.5,"unit":"cup","note":"chopped"},{"item":"kosher salt","qty":0.5,"unit":"tsp","note":"to taste"},{"item":"black pepper","qty":0.25,"unit":"tsp","note":"to taste"}]}'::jsonb),
('southern-bytes-biscuits-and-sausage-gravy', 'Biscuits and Sausage Gravy', 'Southern', 'Southern Bytes', 'https://southern-bytes.com/biscuits-and-sausage-gravy/', 25, 6, 2, 1, 2, 8, 37, array['sausage', 'milk', 'flour', 'biscuit']::text[], '{"title":"Biscuits and Sausage Gravy","cuisine":"Southern","source":"Southern Bytes","url":"https://southern-bytes.com/biscuits-and-sausage-gravy/","minutes":25,"servings":6,"key":["Pork sausage","Milk","Flour","Biscuits"],"minor":["Black pepper","Seasoned salt"],"amounts":{"Pork sausage":"1 lb","Milk":"3 cups","Flour":"1/3 cup","Biscuits":"6-8"},"steps":[["Bake or warm [[6]] biscuits.",null],["Brown [[1 lb]] pork sausage in a large skillet over medium heat, breaking it up, until no pink is left.",8],["Pour off most of the grease, leaving 1 to 2 tablespoons in the pan with the sausage.",null],["Sprinkle [[0.33 cup]] flour over the sausage and stir to coat. Cook a couple of minutes to toast the flour.",2],["Slowly pour in a little of the [[3 cups]] milk while stirring. Once it thickens, add the rest.",null],["Simmer, stirring often, until the gravy is thick.",10],["Season with [[2.5 tsp]] black pepper and [[0.5 tsp]] seasoned salt. It thickens more as it cools.",null],["Split the biscuits and spoon the gravy over them. Serve right away.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":449,"protein_g":20,"carbs_g":22,"fat_g":30},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"biscuits","qty":6,"note":"homemade or store-bought, warmed"},{"item":"pork sausage","qty":1,"unit":"lb","note":"hot or mild"},{"item":"all-purpose flour","qty":0.33,"unit":"cup"},{"item":"milk","qty":3,"unit":"cup","note":"2% or whole"},{"item":"black pepper","qty":2.5,"unit":"tsp","note":"freshly ground"},{"item":"seasoned salt","qty":0.5,"unit":"tsp"}]}'::jsonb),
('sprinklebakes-depression-era-peanut-butter-bread', 'Depression-Era Peanut Butter Bread', 'American', 'Sprinkle Bakes (from a 1932 Five Roses Flour recipe shared on r/Old_Recipes)', 'https://www.sprinklebakes.com/2020/08/depression-era-peanut-butter-bread.html', 85, 10, 1, 1, 3, 7, 46, array['flour', 'butter', 'milk', 'honey']::text[], '{"title":"Depression-Era Peanut Butter Bread","cuisine":"American","source":"Sprinkle Bakes (from a 1932 Five Roses Flour recipe shared on r/Old_Recipes)","url":"https://www.sprinklebakes.com/2020/08/depression-era-peanut-butter-bread.html","minutes":85,"servings":10,"key":["Flour","Peanut butter","Milk","Honey"],"minor":["Sugar","Baking powder","Salt"],"amounts":{"Flour":"2 cups","Peanut butter":"1 1/2 cups creamy","Milk":"1 1/3 cups","Honey":"1/4 cup"},"steps":[["Heat the oven to 325°F and grease a 9x5-inch loaf pan.",null],["In a large bowl, whisk [[2 cups]] flour, [[0.25 cup]] sugar, [[4 tsp]] baking powder and [[0.5 tsp]] salt.",null],["In another bowl, stir [[1.5 cups]] peanut butter with [[0.25 cup]] honey.",null],["Add the peanut butter mix and [[1.33 cups]] milk to the flour. Mix just until combined, then fold by hand to get rid of any flour streaks.",null],["Spread the thick batter in the pan and smooth the top.",null],["Bake until a toothpick near the center comes out clean. Cover loosely with foil if the top browns too fast.",65],["Cool in the pan 5 minutes, then turn out onto a rack. Slice with a serrated knife and serve warm with butter.",5]],"technique":1,"prep":1,"precision":3,"nutrition":{"calories":370,"protein_g":13,"carbs_g":36,"fat_g":21},"video":null,"country":"US","effort_steps":5,"ingredients":[{"item":"all-purpose flour","qty":2,"unit":"cup"},{"item":"sugar","qty":0.25,"unit":"cup"},{"item":"baking powder","qty":4,"unit":"tsp"},{"item":"fine salt","qty":0.5,"unit":"tsp"},{"item":"creamy peanut butter","qty":1.5,"unit":"cup"},{"item":"honey","qty":0.25,"unit":"cup"},{"item":"milk","qty":1.33,"unit":"cup"}]}'::jsonb),
('martymadeit-poulet-a-la-moambe', 'Poulet à la Moambe', 'Congolese', 'Marty Made It', 'https://martymadeit.com/2017/05/15/039-democratic-republic-of-the-congo-poulet-a-la-moambe/', 150, 6, 2, 2, 2, 7, 60, array['chicken', 'butter', 'tomatoes', 'onion']::text[], '{"title":"Poulet à la Moambe","cuisine":"Congolese","source":"Marty Made It","url":"https://martymadeit.com/2017/05/15/039-democratic-republic-of-the-congo-poulet-a-la-moambe/","minutes":150,"servings":6,"key":["Chicken pieces","Peanut butter","Tomato sauce","Onion"],"minor":["Salt","Black pepper","Cayenne pepper","Nutmeg","Butter"],"amounts":{"Chicken pieces":"3-4 lb, cut into serving pieces","Peanut butter":"1 cup creamy, unsalted","Tomato sauce":"1 (8 oz) can","Onion":"1, minced"},"steps":[["Put [[3.5 lb]] chicken pieces in a large pot, cover with water and add [[0.5 tsp]] salt and some black pepper.",null],["Bring to a boil, then lower the heat and simmer until the chicken is tender, about 1 to 1.5 hours.",75],["Lift out the chicken and save [[1.5 cups]] of the broth.",null],["In a large oven-safe pot, melt [[1 tbsp]] butter. Add [[1]] minced onion, [[0.25 tsp]] cayenne and a pinch of nutmeg and cook for about 3 minutes.",3],["Stir in [[8 oz]] tomato sauce, then add the chicken and the saved broth. Cover and simmer for 15 minutes.",15],["Heat the oven to 350°F (175°C). Stir [[1 cup]] peanut butter into the sauce until smooth and thick.",null],["Bake uncovered for 30 minutes. Serve warm over rice.",30]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":560,"protein_g":42,"carbs_g":12,"fat_g":39},"video":null,"country":"CD","effort_steps":4,"ingredients":[{"item":"chicken pieces","qty":3.5,"unit":"lb","note":"cut into serving pieces"},{"item":"salt","qty":0.5,"unit":"tsp"},{"item":"black pepper","qty":0.25,"unit":"tsp"},{"item":"butter","qty":1,"unit":"tbsp"},{"item":"onion","qty":1,"note":"minced"},{"item":"cayenne pepper","qty":0.25,"unit":"tsp"},{"item":"nutmeg","qty":1,"unit":"pinch"},{"item":"tomato sauce","qty":8,"unit":"oz","note":"1 can"},{"item":"creamy unsalted peanut butter","qty":1,"unit":"cup"}]}'::jsonb),
('eatwellabi-congolese-cassava-leaf-soup-pondu', 'Pondu (Congolese Cassava Leaf Stew)', 'Congolese', 'Eat Well Abi', 'https://eatwellabi.com/congolese-cassava-leaf-soup-pondu/', 115, 8, 2, 2, 1, 7, 59, array['cassava leave', 'oil', 'leek', 'eggplant', 'sardine', 'onion']::text[], '{"title":"Pondu (Congolese Cassava Leaf Stew)","cuisine":"Congolese","source":"Eat Well Abi","url":"https://eatwellabi.com/congolese-cassava-leaf-soup-pondu/","minutes":115,"servings":8,"key":["Cassava leaves","Palm oil","Leeks","Eggplant","Sardines","Spring onions"],"minor":["Green pepper","Garlic","Scotch bonnet pepper","Bouillon cubes","Salt"],"amounts":{"Cassava leaves":"500 g, frozen ground","Palm oil":"1/4 cup","Leeks":"2","Eggplant":"1/2 medium","Sardines":"3 cans","Spring onions":"5"},"steps":[["Thaw [[500 g]] frozen cassava leaves, rinse them in a colander and squeeze out the extra water.",null],["Wash [[2]] leeks, [[5]] spring onions and [[1]] green pepper. Peel [[1 head]] garlic. Cut [[0.5]] eggplant into cubes.",null],["Roughly blend the leeks, spring onions, green pepper and garlic.",null],["Put the blended vegetables in a pot with the cassava leaves and [[2]] bouillon cubes. Cook for 30 minutes, stirring now and then.",30],["Add [[1 cup]] water, [[0.25 cup]] palm oil, the eggplant and [[1]] whole scotch bonnet. Cook on low for 1 hour.",60],["Taste and add salt. Add [[3 cans]] sardines and cook 10 minutes more.",10],["Serve hot with rice or fufu.",null]],"technique":2,"prep":2,"precision":1,"nutrition":{"calories":250,"protein_g":14,"carbs_g":12,"fat_g":16},"video":null,"country":"CD","effort_steps":5,"ingredients":[{"item":"frozen cassava leaves","qty":500,"unit":"g"},{"item":"leeks","qty":2},{"item":"green pepper","qty":1},{"item":"garlic","qty":1,"unit":"head","note":"peeled"},{"item":"spring onions","qty":5},{"item":"bouillon cubes","qty":2},{"item":"palm oil","qty":0.25,"unit":"cup"},{"item":"eggplant","qty":0.5,"unit":"medium","note":"cubed"},{"item":"scotch bonnet pepper","qty":1},{"item":"canned sardines","qty":3,"unit":"can"},{"item":"water","qty":1,"unit":"cup"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"}]}'::jsonb),
('kscuisine-nigerian-party-jollof-rice', 'Nigerian Party Jollof Rice', 'Nigerian', 'K''s Cuisine', 'https://kscuisine.com/jollof-rice/', 55, 8, 3, 2, 3, 9, 59, array['rice', 'bell peppers', 'tomatoes', 'onion', 'broth']::text[], '{"title":"Nigerian Party Jollof Rice","cuisine":"Nigerian","source":"K''s Cuisine","url":"https://kscuisine.com/jollof-rice/","minutes":55,"servings":8,"key":["Rice","Bell peppers","Canned tomatoes","Tomato puree","Onions","Chicken broth"],"minor":["Scotch bonnet peppers","Vegetable oil","Butter","Curry powder","Dried thyme","White pepper","Stock cubes","Salt","Fresh tomatoes"],"amounts":{"Rice":"5 cups parboiled long-grain","Bell peppers":"3 large","Canned tomatoes":"400 g","Tomato puree":"150 g","Onions":"2 large","Chicken broth":"4 cups"},"steps":[["Blend [[3]] bell peppers, [[1]] scotch bonnet, [[400 g]] canned tomatoes and [[1]] red onion until smooth.",null],["Rinse [[5 cups]] rice well until the water runs clear, then drain.",null],["Slice the other onion. Heat [[0.5 cup]] vegetable oil in a large pot and fry half the sliced onion with [[150 g]] tomato puree for 3 minutes, stirring constantly.",3],["Add the blended pepper mix, [[5]] stock cubes, [[1.5 tbsp]] curry powder, [[1.5 tbsp]] dried thyme and [[1 tsp]] white pepper. Fry for 5 to 8 minutes.",7],["Pour in [[4 cups]] chicken broth and [[3.5 cups]] water and bring to a boil. Add [[2 tbsp]] butter.",null],["Stir in the rice, cover the pot with foil and the lid, and cook on low heat for 15 minutes.",15],["Gently fold the sauce through the rice without scraping the bottom.",null],["Top with the rest of the sliced onion and [[2]] sliced tomatoes, cover and cook 5 more minutes.",5],["Stir once more, letting the bottom catch a little for a smoky taste. Add salt to taste and serve.",null]],"technique":3,"prep":2,"precision":3,"nutrition":{"calories":520,"protein_g":9,"carbs_g":92,"fat_g":14},"video":null,"country":"NG","effort_steps":8,"ingredients":[{"item":"long-grain parboiled rice","qty":5,"unit":"cup"},{"item":"scotch bonnet peppers","qty":1},{"item":"bell peppers","qty":3,"unit":"large"},{"item":"canned tomatoes","qty":400,"unit":"g"},{"item":"onions","qty":2,"unit":"large","note":"1 blended, 1 sliced"},{"item":"fresh tomatoes","qty":2,"note":"sliced"},{"item":"tomato puree","qty":150,"unit":"g"},{"item":"vegetable oil","qty":0.5,"unit":"cup"},{"item":"butter","qty":2,"unit":"tbsp"},{"item":"curry powder","qty":1.5,"unit":"tbsp"},{"item":"dried thyme","qty":1.5,"unit":"tbsp"},{"item":"white pepper","qty":1,"unit":"tsp"},{"item":"stock cubes","qty":5},{"item":"chicken broth","qty":4,"unit":"cup"},{"item":"water","qty":3.5,"unit":"cup"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"}]}'::jsonb),
('simshomekitchen-efo-riro', 'Efo Riro (Nigerian Spinach Stew)', 'Nigerian', 'Sims Home Kitchen', 'https://simshomekitchen.com/efo-riro/', 40, 6, 2, 3, 2, 7, 45, array['spinach', 'tomatoes', 'bell peppers', 'oil', 'cooked assorted meat', 'shrimp', 'smoked mackerel']::text[], '{"title":"Efo Riro (Nigerian Spinach Stew)","cuisine":"Nigerian","source":"Sims Home Kitchen","url":"https://simshomekitchen.com/efo-riro/","minutes":40,"servings":6,"key":["Spinach","Canned tomatoes","Red bell pepper","Palm oil","Cooked assorted meat","Dried shrimp","Smoked mackerel"],"minor":["Scotch bonnet peppers","Onion","Iru (locust beans)","Chicken stock","Stock cubes","Salt"],"amounts":{"Spinach":"4 bunches","Canned tomatoes":"1 can plum tomatoes","Red bell pepper":"1","Palm oil":"1/3 cup","Cooked assorted meat":"1 lb, precooked","Dried shrimp":"1/2 cup","Smoked mackerel":"1/4 cup flaked"},"steps":[["Blend [[1 can]] plum tomatoes, [[1]] red bell pepper, [[1]] onion and [[2]] scotch bonnets until smooth.",null],["Wash and chop [[4 bunches]] spinach. Set aside.",null],["Heat [[0.33 cup]] palm oil in a pot and add [[1.5 tbsp]] iru. Stir for a few seconds.",null],["Pour in the blended pepper mix and [[0.5 cup]] chicken stock. Bring to a boil, add [[1]] stock cube and salt, then simmer for 10 to 15 minutes.",12],["Add [[1 lb]] precooked assorted meat and cook another 10 to 15 minutes.",12],["Stir in the spinach and turn the heat down. After 5 minutes add [[0.5 cup]] shrimp and [[0.25 cup]] flaked smoked mackerel.",5],["Cook 7 to 10 more minutes, then serve with rice, pounded yam, eba or amala.",8]],"technique":2,"prep":3,"precision":2,"nutrition":{"calories":330,"protein_g":26,"carbs_g":10,"fat_g":21},"video":null,"country":"NG","effort_steps":5,"ingredients":[{"item":"canned plum tomatoes","qty":1,"unit":"can"},{"item":"red bell pepper","qty":1},{"item":"scotch bonnet peppers","qty":2},{"item":"onion","qty":1},{"item":"chicken stock","qty":0.5,"unit":"cup"},{"item":"stock cube","qty":1},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"},{"item":"precooked assorted meat","qty":1,"unit":"lb","note":"beef, chicken or pomo"},{"item":"red root spinach","qty":4,"unit":"bunch"},{"item":"dried shrimp","qty":0.5,"unit":"cup"},{"item":"smoked mackerel","qty":0.25,"unit":"cup","note":"flaked"},{"item":"palm oil","qty":0.33,"unit":"cup"},{"item":"iru (fermented locust beans)","qty":1.5,"unit":"tbsp"}]}'::jsonb),
('eatwithafia-ghanaian-beans-stew-red-red', 'Red Red (Ghanaian Bean Stew)', 'Ghanaian', 'Eat With Afia', 'https://eatwithafia.com/ghanaian-beans-stew-red-red/', 85, 8, 2, 2, 2, 6, 51, array['peas', 'oil', 'tomatoes', 'onion']::text[], '{"title":"Red Red (Ghanaian Bean Stew)","cuisine":"Ghanaian","source":"Eat With Afia","url":"https://eatwithafia.com/ghanaian-beans-stew-red-red/","minutes":85,"servings":8,"key":["Black-eyed peas","Red palm oil","Tomatoes","Tomato sauce","Red onion"],"minor":["Red bell pepper","Garlic","Ginger","Scotch bonnet pepper","Curry powder","Ground cumin","Ground cloves","Bay leaves","Bouillon powder","Tomato paste"],"amounts":{"Black-eyed peas":"2 cups dried, soaked","Red palm oil":"1/4 cup","Tomatoes":"3","Tomato sauce":"1 2/3 cups (398 ml can)","Red onion":"1 medium"},"steps":[["Soak [[2 cups]] dried black-eyed peas overnight. Drain, cover with fresh water and simmer until tender, about 45 to 50 minutes.",45],["Finely chop half of [[1]] red onion. Blend the other half with [[3]] tomatoes, [[0.5]] red bell pepper, [[1]] scotch bonnet, [[2 cloves]] garlic, [[1 thumb]] ginger and a splash of water.",null],["Heat [[0.25 cup]] red palm oil in a large pot and cook the chopped onion until soft.",4],["Stir in [[0.25 cup]] tomato paste, then the blended mixture, [[1.67 cups]] tomato sauce, [[1 tbsp]] curry powder, [[1 tbsp]] cumin, [[1 tsp]] cloves, [[2]] bay leaves and [[1 tbsp]] bouillon powder.",null],["Cover and simmer for about 30 minutes, until the sauce is thick.",30],["Drain the beans, stir them into the sauce and simmer for 10 minutes. Serve with fried plantains or rice.",10]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":250,"protein_g":11,"carbs_g":33,"fat_g":8},"video":null,"country":"GH","effort_steps":4,"ingredients":[{"item":"dried black-eyed peas","qty":2,"unit":"cup","note":"soaked overnight"},{"item":"red onion","qty":1,"unit":"medium"},{"item":"red bell pepper","qty":0.5},{"item":"tomatoes","qty":3},{"item":"garlic","qty":2,"unit":"clove"},{"item":"ginger","qty":1,"unit":"thumb"},{"item":"scotch bonnet pepper","qty":1},{"item":"curry powder","qty":1,"unit":"tbsp"},{"item":"ground cumin","qty":1,"unit":"tbsp"},{"item":"ground cloves","qty":1,"unit":"tsp"},{"item":"bay leaves","qty":2},{"item":"vegetable bouillon powder","qty":1,"unit":"tbsp"},{"item":"tomato paste","qty":0.25,"unit":"cup"},{"item":"red palm oil","qty":0.25,"unit":"cup"},{"item":"tomato sauce","qty":1.67,"unit":"cup"}]}'::jsonb),
('marocmama-senegalese-chicken-yassa', 'Senegalese Chicken Yassa', 'Senegalese', 'MarocMama', 'https://marocmama.com/senegalese-chicken-yassa/', 90, 6, 2, 2, 2, 8, 55, array['chicken', 'onion', 'lemon', 'carrots', 'green olive', 'rice']::text[], '{"title":"Senegalese Chicken Yassa","cuisine":"Senegalese","source":"MarocMama","url":"https://marocmama.com/senegalese-chicken-yassa/","minutes":90,"servings":6,"key":["Whole chicken","Onions","Lemon juice","Carrots","Green olives","Rice"],"minor":["Scotch bonnet pepper","Peanut oil","Dijon mustard","Salt","Black pepper"],"amounts":{"Whole chicken":"1 (2.5-3.5 lb), cut into pieces","Onions":"4 large, thinly sliced","Lemon juice":"1/2 cup","Carrots":"4, thinly sliced","Green olives":"1/2 cup pimento-stuffed","Rice":"for serving"},"steps":[["In a large bowl mix [[0.5 cup]] lemon juice, [[0.125 tsp]] minced scotch bonnet, [[4]] thinly sliced onions, salt and pepper.",null],["Add [[1]] chicken cut into pieces, cover and refrigerate for at least 3 hours, or overnight.",null],["Heat the broiler. Lift the chicken out of the marinade (keep the onions and juice) and broil until lightly browned on both sides.",15],["Heat [[1 tbsp]] peanut oil in a Dutch oven. Add the onions from the marinade and cook slowly until soft and see-through.",12],["Pour in the rest of the marinade and heat it through.",null],["Add the chicken, [[1]] whole scotch bonnet pricked with a fork, [[0.5 cup]] olives, [[4]] sliced carrots, [[1 tbsp]] Dijon mustard and [[0.5 cup]] water.",null],["Bring to a gentle boil, then lower the heat and simmer for about 30 minutes, until the chicken is cooked through.",30],["Season with salt and pepper and serve over white rice.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":610,"protein_g":38,"carbs_g":52,"fat_g":27},"video":null,"country":"SN","effort_steps":5,"ingredients":[{"item":"whole chicken","qty":1,"note":"2.5-3.5 lb, cut into pieces"},{"item":"onions","qty":4,"unit":"large","note":"thinly sliced"},{"item":"lemon juice","qty":0.5,"unit":"cup"},{"item":"scotch bonnet pepper","qty":0.125,"unit":"tsp","note":"minced"},{"item":"peanut oil","qty":1,"unit":"tbsp"},{"item":"scotch bonnet pepper","qty":1,"note":"whole, pricked"},{"item":"pimento-stuffed olives","qty":0.5,"unit":"cup"},{"item":"carrots","qty":4,"note":"thinly sliced"},{"item":"Dijon mustard","qty":1,"unit":"tbsp"},{"item":"water","qty":0.5,"unit":"cup"},{"item":"white rice","qty":2,"unit":"cup","note":"uncooked, cooked for serving"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"},{"item":"black pepper","qty":1,"unit":"pinch","note":"to taste"}]}'::jsonb),
('theafricangourmet-ugali-sukuma-wiki', 'Ugali and Sukuma Wiki', 'Kenyan', 'The African Gourmet', 'https://www.theafricangourmet.com/2011/01/ugali-sukuma-wiki-traditional-kenyan.html', 40, 6, 2, 1, 2, 7, 41, array['collard green', 'white cornmeal', 'tomatoes', 'onion']::text[], '{"title":"Ugali and Sukuma Wiki","cuisine":"Kenyan","source":"The African Gourmet","url":"https://www.theafricangourmet.com/2011/01/ugali-sukuma-wiki-traditional-kenyan.html","minutes":40,"servings":6,"key":["Collard greens","White cornmeal","Tomatoes","Onion"],"minor":["Vegetable broth","Vegetable oil","Salt"],"amounts":{"Collard greens":"2 lb, chopped","White cornmeal":"4 cups finely ground","Tomatoes":"3 ripe, chopped","Onion":"1 large white, chopped"},"steps":[["Heat [[2 tbsp]] vegetable oil in a large pot over medium-high heat. Add [[1]] chopped onion and cook for 2 minutes.",2],["Add [[2 lb]] chopped collard greens and [[1 cup]] vegetable broth. Cover and cook about 20 minutes, until soft.",20],["Stir in [[3]] chopped tomatoes and salt to taste. Cover and cook 5 more minutes.",5],["Meanwhile, bring [[8 cups]] water to a boil in another heavy pot.",null],["Slowly pour in [[4 cups]] cornmeal while stirring hard with a wooden spoon, pressing out any lumps.",null],["Keep stirring until the ugali is stiff like soft bread dough and pulls away from the pot, about 5 minutes.",5],["Turn the ugali out onto a plate, shape it into a mound and serve right away with the sukuma wiki.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":420,"protein_g":11,"carbs_g":78,"fat_g":7},"video":null,"country":"KE","effort_steps":6,"ingredients":[{"item":"collard greens","qty":2,"unit":"lb","note":"chopped"},{"item":"vegetable broth","qty":1,"unit":"cup"},{"item":"vegetable oil","qty":2,"unit":"tbsp"},{"item":"white onion","qty":1,"unit":"large","note":"chopped"},{"item":"ripe tomatoes","qty":3,"note":"chopped"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"},{"item":"finely ground white cornmeal","qty":4,"unit":"cup"},{"item":"water","qty":8,"unit":"cup"}]}'::jsonb),
('foodleclub-easy-chakalaka', 'Chakalaka', 'South African', 'Foodle Club', 'https://www.foodleclub.com/easy-chakalaka-recipe/', 30, 8, 1, 2, 2, 6, 34, array['baked bean', 'tomatoes', 'cabbage', 'carrots', 'bell peppers', 'onion']::text[], '{"title":"Chakalaka","cuisine":"South African","source":"Foodle Club","url":"https://www.foodleclub.com/easy-chakalaka-recipe/","minutes":30,"servings":8,"key":["Baked beans","Canned tomatoes","Cabbage","Carrots","Bell peppers","Onion"],"minor":["Fresh chillies","Garlic","Ginger paste","Curry powder","Dried thyme","Paprika","Salt","Sunflower oil"],"amounts":{"Baked beans":"14 oz (400 g) can","Canned tomatoes":"14 oz (400 g) can, chopped","Cabbage":"2 cups shredded","Carrots":"2 medium, grated","Bell peppers":"1 red + 1 green, diced","Onion":"1 large, diced"},"steps":[["Heat [[2 tbsp]] sunflower oil in a large pan. Fry [[1]] diced onion with [[1]] sliced chilli for 4 to 5 minutes.",5],["Add [[3 cloves]] minced garlic, [[0.5 tsp]] ginger paste, [[1 tbsp]] curry powder, [[1 tsp]] paprika, [[1 tsp]] salt and [[1 tsp]] dried thyme. Cook for 1 minute.",1],["Pour in [[400 g]] canned tomatoes, swish [[0.25 cup]] water around the can and add it too. Bring to a boil.",null],["Lower the heat and stir in [[2 cups]] shredded cabbage, [[2]] grated carrots and [[2]] diced bell peppers.",null],["Cover and simmer for 15 minutes, until the vegetables are soft.",15],["Stir in [[400 g]] baked beans and heat for 3 to 4 minutes. Serve hot with pap, rice or grilled meat.",4]],"technique":1,"prep":2,"precision":2,"nutrition":{"calories":120,"protein_g":4,"carbs_g":18,"fat_g":4},"video":null,"country":"ZA","effort_steps":5,"ingredients":[{"item":"cabbage","qty":2,"unit":"cup","note":"shredded"},{"item":"carrots","qty":2,"unit":"medium","note":"grated"},{"item":"onion","qty":1,"unit":"large","note":"diced"},{"item":"red bell pepper","qty":1,"unit":"medium","note":"diced"},{"item":"green bell pepper","qty":1,"unit":"medium","note":"diced"},{"item":"canned chopped tomatoes","qty":400,"unit":"g"},{"item":"water","qty":0.25,"unit":"cup"},{"item":"baked beans in tomato sauce","qty":400,"unit":"g"},{"item":"fresh chilli","qty":1,"note":"sliced, optional"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"ginger paste","qty":0.5,"unit":"tsp"},{"item":"curry powder","qty":1,"unit":"tbsp"},{"item":"dried thyme","qty":1,"unit":"tsp"},{"item":"paprika","qty":1,"unit":"tsp"},{"item":"salt","qty":1,"unit":"tsp"},{"item":"sunflower oil","qty":2,"unit":"tbsp"}]}'::jsonb),
('savorythoughts-diri-kole-ak-pwa-rouj', 'Diri Kole ak Pwa Rouj (Haitian Rice and Red Beans)', 'Haitian', 'Savory Thoughts', 'https://www.savorythoughts.com/diri-kole-ak-pwa-rouj-haitian-red-beans-rice/', 55, 6, 2, 1, 2, 8, 45, array['kidney beans', 'rice', 'onion', 'garlic']::text[], '{"title":"Diri Kole ak Pwa Rouj (Haitian Rice and Red Beans)","cuisine":"Haitian","source":"Savory Thoughts","url":"https://www.savorythoughts.com/diri-kole-ak-pwa-rouj-haitian-red-beans-rice/","minutes":55,"servings":6,"key":["Red kidney beans","Jasmine rice","Onion","Garlic"],"minor":["Fresh thyme","Fresh parsley","Olive oil","Haitian epis or seasoning","Kosher salt"],"amounts":{"Red kidney beans":"2 cups dried","Jasmine rice":"2 1/2 cups, rinsed","Onion":"1/4 cup chopped","Garlic":"4 cloves, minced"},"steps":[["Rinse [[2 cups]] dried red beans. Cook them with [[8 cups]] water in a pressure cooker for about 25 minutes (or simmer on the stove until tender).",25],["Drain the beans and save the cooking liquid. You need [[3.5 cups]] of it.",null],["Heat [[2 tbsp]] olive oil in a medium pot over medium-high heat. Cook [[0.25 cup]] chopped onion and [[4 cloves]] minced garlic for about 1 minute.",1],["Add the beans and stir for 1 to 2 minutes.",2],["Add [[2.5 cups]] rinsed jasmine rice, [[1 tbsp]] seasoning, [[1 tsp]] salt, the saved bean liquid, [[6]] thyme sprigs and [[5]] parsley sprigs.",null],["Lower the heat to medium-low and partly cover. Cook until the liquid is absorbed.",10],["Turn the heat to low, cover fully and cook until the rice is tender, about 15 minutes.",15],["Remove the herb sprigs, fluff with a fork and serve.",null]],"technique":2,"prep":1,"precision":2,"nutrition":{"calories":480,"protein_g":16,"carbs_g":90,"fat_g":6},"video":null,"country":"HT","effort_steps":6,"ingredients":[{"item":"dried red kidney beans","qty":2,"unit":"cup"},{"item":"water","qty":8,"unit":"cup"},{"item":"onion","qty":0.25,"unit":"cup","note":"chopped"},{"item":"fresh thyme","qty":6,"unit":"sprig"},{"item":"fresh parsley","qty":5,"unit":"sprig"},{"item":"garlic","qty":4,"unit":"clove","note":"minced"},{"item":"olive oil","qty":2,"unit":"tbsp"},{"item":"Haitian seasoning (epis or Jacmel seasoning)","qty":1,"unit":"tbsp"},{"item":"kosher salt","qty":1,"unit":"tsp"},{"item":"jasmine rice","qty":2.5,"unit":"cup","note":"rinsed"},{"item":"bean cooking liquid","qty":3.5,"unit":"cup","note":"reserved"}]}'::jsonb),
('foreignfork-mangu-dominican-mashed-plantains', 'Mangú (Dominican Mashed Plantains)', 'Dominican', 'The Foreign Fork', 'https://foreignfork.com/mangu/', 35, 4, 1, 1, 1, 6, 30, array['green plantain', 'onion', 'butter']::text[], '{"title":"Mangú (Dominican Mashed Plantains)","cuisine":"Dominican","source":"The Foreign Fork","url":"https://foreignfork.com/mangu/","minutes":35,"servings":4,"key":["Green plantains","Red onion","Butter"],"minor":["White vinegar","Salt","Vegetable oil"],"amounts":{"Green plantains":"4","Red onion":"1/2, sliced into thin rings","Butter":"4-5 tbsp unsalted, softened"},"steps":[["Mix [[0.5]] red onion sliced into thin rings with [[6 tbsp]] white vinegar and [[0.5 tsp]] salt. Let it sit 20 to 30 minutes.",null],["Peel [[4]] green plantains and cut each into about 6 pieces.",null],["Boil the plantains in water with [[2 tsp]] salt until a fork slides in easily, about 20 minutes. Drain, but save a cup of the cooking water.",20],["Heat [[0.25 cup]] vegetable oil in a small pot. Add the onions and their vinegar and cook about 5 minutes until soft.",5],["Mash the plantains with [[4 tbsp]] butter, a splash of the cooking water and a little of the onion oil until smooth and creamy.",null],["Taste and add salt. Serve topped with the onions, with fried cheese, salami or eggs on the side.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":420,"protein_g":3,"carbs_g":58,"fat_g":22},"video":null,"country":"DO","effort_steps":5,"ingredients":[{"item":"red onion","qty":0.5,"note":"thin rings"},{"item":"white vinegar","qty":6,"unit":"tbsp"},{"item":"green plantains","qty":4},{"item":"salt","qty":2.5,"unit":"tsp","note":"divided"},{"item":"vegetable oil","qty":0.25,"unit":"cup"},{"item":"unsalted butter","qty":4,"unit":"tbsp","note":"softened"}]}'::jsonb),
('dailynexus-lolos-chicken-adobo', 'Lolo''s Chicken Adobo', 'Filipino', 'Daily Nexus (family recipe)', 'https://dailynexus.com/2022-10-20/chicken-adobo-a-filipino-chicken-stew/', 110, 4, 2, 1, 1, 7, 57, array['chicken', 'white vinegar', 'soy sauce', 'garlic']::text[], '{"title":"Lolo''s Chicken Adobo","cuisine":"Filipino","source":"Daily Nexus (family recipe)","url":"https://dailynexus.com/2022-10-20/chicken-adobo-a-filipino-chicken-stew/","minutes":110,"servings":4,"key":["Chicken thighs","White vinegar","Soy sauce","Garlic"],"minor":["Black peppercorns","Bay leaf","Vegetable oil","Parsley"],"amounts":{"Chicken thighs":"2 lb (about 4)","White vinegar":"1/2 cup","Soy sauce":"1/4 cup","Garlic":"3 cloves, minced"},"steps":[["In a bowl mix [[0.5 cup]] white vinegar, [[0.5 cup]] water, [[0.25 cup]] soy sauce, [[6]] peppercorns, [[3 cloves]] minced garlic and [[1]] bay leaf.",null],["Add [[2 lb]] chicken thighs and marinate for 1 hour, turning them now and then.",null],["Take the chicken out and pat it dry. Keep the marinade.",null],["Heat [[1.5 tbsp]] vegetable oil in a pan over medium heat and brown the chicken well on both sides.",8],["Pour in the marinade and bring to a boil. Cover and simmer on low for 30 to 45 minutes, until tender.",40],["Take out the chicken. Boil the sauce until about [[0.5 cup]] is left.",5],["Spoon the sauce over the chicken, sprinkle with parsley and serve with rice.",null]],"technique":2,"prep":1,"precision":1,"nutrition":{"calories":430,"protein_g":40,"carbs_g":4,"fat_g":27},"video":null,"country":"PH","effort_steps":6,"ingredients":[{"item":"chicken thighs","qty":2,"unit":"lb","note":"about 4"},{"item":"white vinegar","qty":0.5,"unit":"cup"},{"item":"water","qty":0.5,"unit":"cup"},{"item":"soy sauce","qty":0.25,"unit":"cup"},{"item":"whole black peppercorns","qty":6},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"bay leaf","qty":1},{"item":"vegetable oil","qty":1.5,"unit":"tbsp"},{"item":"parsley","qty":1,"unit":"tbsp","note":"to garnish"}]}'::jsonb),
('norecipes-tamago-kake-gohan', 'Tamago Kake Gohan (Egg on Rice)', 'Japanese', 'No Recipes', 'https://norecipes.com/tamago-kake-gohan-egg-rice/', 2, 1, 1, 1, 1, 5, 22, array['rice', 'eggs']::text[], '{"title":"Tamago Kake Gohan (Egg on Rice)","cuisine":"Japanese","source":"No Recipes","url":"https://norecipes.com/tamago-kake-gohan-egg-rice/","minutes":2,"servings":1,"key":["Rice","Eggs"],"minor":["Soy sauce"],"amounts":{"Rice":"1 bowl hot cooked short-grain","Eggs":"1 very fresh"},"steps":[["Put [[1 bowl]] piping hot cooked short-grain rice in a deep bowl.",null],["Crack [[1]] very fresh egg over the rice and set the yolk aside.",null],["Stir the egg white into the hot rice until it turns fluffy and slightly thick.",null],["Make a small well on top and slide the yolk into it.",null],["Drizzle with [[1 tsp]] soy sauce, mix the yolk in and eat right away.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":320,"protein_g":11,"carbs_g":54,"fat_g":5},"video":null,"country":"JP","effort_steps":5,"ingredients":[{"item":"cooked Japanese short-grain rice","qty":1,"unit":"cup","note":"piping hot"},{"item":"egg","qty":1,"note":"very fresh"},{"item":"soy sauce","qty":1,"unit":"tsp","note":"to taste"}]}'::jsonb),
('maangchi-kimchi-bokkeumbap', 'Kimchi Bokkeumbap (Kimchi Fried Rice)', 'Korean', 'Maangchi', 'https://www.maangchi.com/recipe/kimchi-bokkeumbap', 10, 2, 1, 1, 1, 6, 26, array['rice', 'kimchi', 'gochujang', 'scallions']::text[], '{"title":"Kimchi Bokkeumbap (Kimchi Fried Rice)","cuisine":"Korean","source":"Maangchi","url":"https://www.maangchi.com/recipe/kimchi-bokkeumbap","minutes":10,"servings":2,"key":["Rice","Kimchi","Gochujang","Green onion"],"minor":["Kimchi juice","Toasted sesame oil","Vegetable oil","Sesame seeds","Roasted seaweed"],"amounts":{"Rice":"3 cups cooked","Kimchi":"1 cup chopped, well-fermented","Gochujang":"2-3 tbsp","Green onion":"1, chopped"},"steps":[["Heat a wide pan and add [[1 tsp]] vegetable oil.",null],["Add [[1 cup]] chopped sour kimchi and stir-fry for about 1 minute over medium-high heat.",1],["Add [[3 cups]] cooked rice, [[0.25 cup]] kimchi juice, [[0.25 cup]] water and [[2 tbsp]] gochujang.",null],["Stir and fry for about 7 minutes, breaking up the rice so it is evenly red.",7],["Turn off the heat and stir in [[3 tsp]] toasted sesame oil.",null],["Top with [[1]] chopped green onion, [[1 sheet]] shredded seaweed and [[1 tbsp]] sesame seeds. Add a fried egg if you like.",null]],"technique":1,"prep":1,"precision":1,"nutrition":{"calories":480,"protein_g":9,"carbs_g":86,"fat_g":11},"video":null,"country":"KR","effort_steps":6,"ingredients":[{"item":"cooked rice","qty":3,"unit":"cup"},{"item":"kimchi","qty":1,"unit":"cup","note":"chopped, well-fermented"},{"item":"kimchi juice","qty":0.25,"unit":"cup"},{"item":"water","qty":0.25,"unit":"cup"},{"item":"gochujang","qty":2,"unit":"tbsp"},{"item":"toasted sesame oil","qty":3,"unit":"tsp"},{"item":"vegetable oil","qty":1,"unit":"tsp"},{"item":"green onion","qty":1,"note":"chopped"},{"item":"roasted sesame seeds","qty":1,"unit":"tbsp"},{"item":"gim (roasted seaweed)","qty":1,"unit":"sheet","note":"shredded"}]}'::jsonb),
('vegrecipesofindia-moong-dal-khichdi', 'Moong Dal Khichdi', 'Indian', 'Dassana''s Veg Recipes', 'https://www.vegrecipesofindia.com/moong-dal-khichdi-recipe/', 40, 2, 1, 1, 2, 8, 38, array['lentils', 'rice', 'onion', 'tomatoes']::text[], '{"title":"Moong Dal Khichdi","cuisine":"Indian","source":"Dassana''s Veg Recipes","url":"https://www.vegrecipesofindia.com/moong-dal-khichdi-recipe/","minutes":40,"servings":2,"key":["Moong dal","Rice","Onion","Tomato"],"minor":["Ghee","Cumin seeds","Green chilli","Ginger","Turmeric","Asafoetida","Salt"],"amounts":{"Moong dal":"1/2 cup split yellow","Rice":"1/2 cup","Onion":"1 small, finely chopped","Tomato":"1 medium, chopped"},"steps":[["Rinse [[0.5 cup]] moong dal and [[0.5 cup]] rice together. Soak in water for 30 minutes, then drain.",null],["Heat [[2 tbsp]] ghee in a pressure cooker and add [[1 tsp]] cumin seeds. Let them sizzle.",null],["Add [[1]] finely chopped onion and cook until see-through.",3],["Add [[1]] chopped tomato, [[0.5 tsp]] chopped green chilli and [[1 tsp]] grated ginger. Cook until the tomato is soft.",3],["Stir in [[0.25 tsp]] turmeric and a pinch of asafoetida.",null],["Add the drained rice and dal and stir for 1 minute. Add [[3.5 cups]] water and salt to taste.",null],["Close the cooker and cook for 7 to 8 whistles (about 9 minutes). Let the pressure drop on its own.",9],["Stir, add hot water if it is too thick, and serve warm with a little extra ghee.",null]],"technique":1,"prep":1,"precision":2,"nutrition":{"calories":390,"protein_g":14,"carbs_g":58,"fat_g":12},"video":null,"country":"IN","effort_steps":8,"ingredients":[{"item":"moong dal","qty":0.5,"unit":"cup"},{"item":"rice","qty":0.5,"unit":"cup"},{"item":"ghee","qty":2,"unit":"tbsp"},{"item":"cumin seeds","qty":1,"unit":"tsp"},{"item":"onion","qty":1,"unit":"small","note":"finely chopped"},{"item":"tomato","qty":1,"unit":"medium","note":"chopped"},{"item":"green chilli","qty":0.5,"unit":"tsp","note":"chopped"},{"item":"ginger","qty":1,"unit":"tsp","note":"grated"},{"item":"turmeric powder","qty":0.25,"unit":"tsp"},{"item":"asafoetida","qty":1,"unit":"pinch","note":"optional"},{"item":"water","qty":3.5,"unit":"cup"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"}]}'::jsonb),
('foreignfork-pakistani-chicken-karahi', 'Pakistani Chicken Karahi', 'Pakistani', 'The Foreign Fork', 'https://foreignfork.com/wprm_print/pakistani-chicken-karahi-recipe', 65, 4, 3, 2, 2, 8, 58, array['chicken', 'tomatoes', 'green chilie', 'garlic', 'ginger']::text[], '{"title":"Pakistani Chicken Karahi","cuisine":"Pakistani","source":"The Foreign Fork","url":"https://foreignfork.com/wprm_print/pakistani-chicken-karahi-recipe","minutes":65,"servings":4,"key":["Bone-in chicken","Tomatoes","Green chilies","Garlic","Ginger"],"minor":["Whole coriander seeds","Cumin seeds","Black peppercorns","Red chili flakes","Vegetable oil","Salt","Chicken bouillon","Fresh coriander"],"amounts":{"Bone-in chicken":"2 lb skinless, karahi cut","Tomatoes":"2 lb ripe","Green chilies":"8","Garlic":"10 cloves","Ginger":"2 inches, in matchsticks"},"steps":[["Toast [[2 tbsp]] coriander seeds, [[2 tbsp]] cumin seeds and [[1 tbsp]] peppercorns in a dry pan until fragrant. Grind them and mix in [[0.5 tsp]] chili flakes.",3],["Heat [[1 cup]] oil in a wok. Fry [[10 cloves]] crushed garlic, then add [[2 lb]] chicken and [[0.5 tbsp]] salt and brown it. Set the chicken aside.",10],["Pour off most of the oil, leaving the garlic in the wok.",null],["In another pot heat [[0.5 cup]] oil with [[5]] slit green chilies and [[2 lb]] whole tomatoes. Cover and cook until the skins split.",10],["Peel the tomatoes, mash them into a sauce and simmer until thick.",5],["Put the wok back on the heat with [[0.5 cup]] oil. Add the chicken, the tomato sauce and [[3 tbsp]] of the spice mix. Cook briefly.",null],["Mix [[0.5 tsp]] chicken bouillon with [[1 tbsp]] water, add to the wok and simmer for about 20 minutes, until the sauce is reduced by half.",20],["Top with [[3]] chopped green chilies, [[2 tbsp]] coriander leaves and [[2 inches]] ginger matchsticks. Serve with naan.",null]],"technique":3,"prep":2,"precision":2,"nutrition":{"calories":620,"protein_g":38,"carbs_g":14,"fat_g":46},"video":null,"country":"PK","effort_steps":7,"ingredients":[{"item":"whole coriander seeds","qty":2,"unit":"tbsp"},{"item":"cumin seeds","qty":2,"unit":"tbsp"},{"item":"black peppercorns","qty":1,"unit":"tbsp"},{"item":"red chili flakes","qty":0.5,"unit":"tsp"},{"item":"vegetable oil","qty":2,"unit":"cup","note":"divided, most is drained off"},{"item":"garlic","qty":10,"unit":"clove","note":"crushed"},{"item":"bone-in skinless chicken","qty":2,"unit":"lb","note":"karahi cut"},{"item":"salt","qty":0.5,"unit":"tbsp"},{"item":"green chilies","qty":8,"note":"5 slit, 3 chopped"},{"item":"ripe tomatoes","qty":2,"unit":"lb"},{"item":"chicken bouillon","qty":0.5,"unit":"tsp"},{"item":"water","qty":1,"unit":"tbsp"},{"item":"fresh coriander leaves","qty":2,"unit":"tbsp"},{"item":"ginger","qty":2,"unit":"inch","note":"matchsticks"}]}'::jsonb),
('irishcentral-colcannon-traditional-irish', 'Colcannon', 'Irish', 'IrishCentral', 'https://www.irishcentral.com/culture/food-drink/colcannon-traditional-irish-recipe', 40, 6, 1, 2, 1, 7, 36, array['potatoes', 'cabbage', 'butter', 'milk']::text[], '{"title":"Colcannon","cuisine":"Irish","source":"IrishCentral","url":"https://www.irishcentral.com/culture/food-drink/colcannon-traditional-irish-recipe","minutes":40,"servings":6,"key":["Potatoes","Cabbage","Butter","Milk"],"minor":["Scallions","Salt","Black pepper","Parsley or chives"],"amounts":{"Potatoes":"4 lb russet","Cabbage":"1 head green","Butter":"1 stick (4 oz)","Milk":"1 cup"},"steps":[["Peel [[4 lb]] potatoes, cut into chunks and boil in salted water until tender, about 20 minutes.",20],["Meanwhile, thinly slice [[1 head]] cabbage and simmer in boiling water for 3 to 5 minutes, until just wilted.",4],["Drain the cabbage, squeeze out the water and toss with a third of [[1 stick]] butter. Cover to keep warm.",null],["Drain the potatoes and put them back in the pot over low heat for a minute to dry out.",1],["Add [[1 cup]] milk, another third of the butter and [[4]] chopped scallions. Warm until the butter melts; do not boil.",null],["Mash the potatoes by hand with a masher, then mix in the cabbage. Season with salt and pepper.",null],["Pile into a bowl, make a well in the middle and drop in the last of the butter. Top with parsley or chives.",null]],"technique":1,"prep":2,"precision":1,"nutrition":{"calories":400,"protein_g":8,"carbs_g":55,"fat_g":17},"video":null,"country":"IE","effort_steps":6,"ingredients":[{"item":"russet potatoes","qty":4,"unit":"lb"},{"item":"green cabbage","qty":1,"unit":"head","note":"thinly sliced"},{"item":"milk","qty":1,"unit":"cup"},{"item":"butter","qty":1,"unit":"stick","note":"divided into thirds"},{"item":"scallions","qty":4,"note":"chopped, optional"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"},{"item":"black pepper","qty":1,"unit":"pinch","note":"to taste"},{"item":"parsley or chives","qty":1,"unit":"tbsp","note":"chopped"}]}'::jsonb),
('justapinch-great-grandma-irenes-haluski', 'Great Grandma Irene''s Haluski', 'Slovak', 'Just A Pinch', 'https://www.justapinch.com/recipes/main-course/pork/great-grandma-irenes-haluski.html', 60, 6, 1, 2, 1, 7, 41, array['cabbage', 'noodles', 'onion', 'bacon', 'butter']::text[], '{"title":"Great Grandma Irene''s Haluski","cuisine":"Slovak","source":"Just A Pinch","url":"https://www.justapinch.com/recipes/main-course/pork/great-grandma-irenes-haluski.html","minutes":60,"servings":6,"key":["Cabbage","Egg noodles","Onions","Bacon","Butter"],"minor":["Garlic","Garlic powder","Olive oil","Salt","Black pepper"],"amounts":{"Cabbage":"1 head","Egg noodles":"12 oz bag","Onions":"2 Vidalia","Bacon":"1 lb","Butter":"1/2 stick"},"steps":[["Cut [[1 lb]] bacon into pieces and fry until cooked but not fully crisp. Lift it out and set aside.",10],["Pour off about half the bacon fat, keeping the rest in the pan.",null],["Boil [[1 head]] cabbage with [[3 cloves]] whole garlic until tender, about 15 minutes. Drain and cut into strips.",15],["About 5 minutes before the cabbage is done, slice [[2]] onions and fry them in the bacon fat.",5],["Add the cabbage to the onions and fry until golden, about 10 minutes.",10],["Meanwhile boil [[12 oz]] egg noodles until tender and drain.",8],["Add the noodles, bacon, [[0.5 stick]] butter and a dash of garlic powder to the pan. Stir until the butter melts, season with salt and pepper and serve hot.",null]],"technique":1,"prep":2,"precision":1,"nutrition":{"calories":560,"protein_g":18,"carbs_g":50,"fat_g":32},"video":null,"country":"SK","effort_steps":6,"ingredients":[{"item":"Vidalia onions","qty":2,"note":"sliced"},{"item":"cabbage","qty":1,"unit":"head"},{"item":"bacon","qty":1,"unit":"lb"},{"item":"butter","qty":0.5,"unit":"stick"},{"item":"egg noodles","qty":12,"unit":"oz"},{"item":"garlic powder","qty":1,"unit":"pinch"},{"item":"olive oil","qty":1,"unit":"tbsp","note":"optional drizzle"},{"item":"garlic","qty":3,"unit":"clove","note":"whole"}]}'::jsonb),
('recipesfromitaly-authentic-cacio-e-pepe', 'Cacio e Pepe', 'Italian', 'Recipes from Italy', 'https://www.recipesfromitaly.com/wprm_print/authentic-cacio-e-pepe-the-real-roman-method', 20, 4, 4, 1, 4, 8, 55, array['pasta', 'pecorino romano', 'black peppercorn']::text[], '{"title":"Cacio e Pepe","cuisine":"Italian","source":"Recipes from Italy","url":"https://www.recipesfromitaly.com/wprm_print/authentic-cacio-e-pepe-the-real-roman-method","minutes":20,"servings":4,"key":["Spaghetti","Pecorino Romano","Black peppercorns"],"minor":["Coarse salt"],"amounts":{"Spaghetti":"350 g (12 oz)","Pecorino Romano":"220 g (2 cups) finely grated","Black peppercorns":"1-1.5 tbsp, coarsely ground"},"steps":[["Finely grate [[220 g]] Pecorino Romano and coarsely grind [[1 tbsp]] black peppercorns.",null],["Toast the pepper in a large dry skillet over medium heat for 2 to 3 minutes, then turn the heat off.",3],["Bring [[7.5 cups]] water to a boil with [[0.5 tbsp]] coarse salt. Use less water and salt than usual. Cook [[350 g]] spaghetti for about 5 minutes.",5],["Add [[1 cup]] pasta water to the pepper skillet and turn the heat to low.",null],["Move the half-cooked pasta into the skillet and finish cooking it there, adding pasta water a little at a time. Save [[1 cup]] starchy water.",4],["In a bowl, stir the cheese with the saved starchy water until it looks like creamy ricotta.",null],["Turn off the heat, wait 30 seconds, then stir the cheese cream into the pasta bit by bit until glossy.",null],["Serve right away with extra pecorino and pepper.",null]],"technique":4,"prep":1,"precision":4,"nutrition":{"calories":600,"protein_g":29,"carbs_g":66,"fat_g":23},"video":null,"country":"IT","effort_steps":8,"ingredients":[{"item":"spaghetti","qty":350,"unit":"g"},{"item":"Pecorino Romano","qty":220,"unit":"g","note":"finely grated"},{"item":"black peppercorns","qty":1.25,"unit":"tbsp","note":"coarsely ground"},{"item":"water","qty":7.5,"unit":"cup"},{"item":"coarse salt","qty":0.5,"unit":"tbsp"}]}'::jsonb),
('familiakitchen-susanas-lomo-saltado', 'Susana''s Lomo Saltado', 'Peruvian', 'Familia Kitchen', 'https://familiakitchen.com/susanas-lomo-saltado/', 65, 6, 3, 3, 2, 8, 61, array['beef', 'potatoes', 'onion', 'tomatoes', 'bell peppers', 'soy sauce']::text[], '{"title":"Susana''s Lomo Saltado","cuisine":"Peruvian","source":"Familia Kitchen","url":"https://familiakitchen.com/susanas-lomo-saltado/","minutes":65,"servings":6,"key":["Sirloin steak","Yellow potatoes","Red onion","Tomatoes","Orange bell pepper","Soy sauce"],"minor":["Red wine vinegar","Ground cumin","Ají amarillo","Garlic","Green onions","Corn","Peas","Cilantro","Vegetable oil","Salt","Black pepper"],"amounts":{"Sirloin steak":"1 lb, thinly sliced","Yellow potatoes":"6, peeled","Red onion":"1 medium","Tomatoes":"2 large, in wedges","Orange bell pepper":"1, in strips","Soy sauce":"2 tbsp"},"steps":[["Mix [[3 tbsp]] red wine vinegar, [[2 tbsp]] soy sauce, [[2 tsp]] cumin, salt and pepper. Add [[1 lb]] thinly sliced sirloin and marinate for 30 minutes.",null],["Cut [[6]] peeled potatoes into thick sticks, soak in water, then pat very dry.",null],["Heat [[3 cups]] vegetable oil and fry the potatoes in batches until light golden. Drain on paper towels and salt them right away.",15],["Drain the steak and sear it in a hot pan until medium rare. Set aside.",4],["In the same pan, quickly cook [[1]] red onion in wedges, [[1]] orange pepper in strips and [[2]] tomatoes in wedges until just tender.",4],["Add [[0.33 cup]] green onion pieces, [[2 cloves]] minced garlic and [[1]] sliced ají amarillo and cook 1 minute.",1],["Return the steak and add [[0.5 cup]] corn and [[0.5 cup]] peas. Cook 5 minutes, adding a splash of soy sauce if dry.",5],["Toss the fries gently with the beef and juices, top with cilantro and serve with white rice.",null]],"technique":3,"prep":3,"precision":2,"nutrition":{"calories":480,"protein_g":24,"carbs_g":42,"fat_g":23},"video":null,"country":"PE","effort_steps":7,"ingredients":[{"item":"red wine vinegar","qty":3,"unit":"tbsp"},{"item":"soy sauce","qty":2,"unit":"tbsp"},{"item":"ground cumin","qty":2,"unit":"tsp"},{"item":"sirloin steak","qty":1,"unit":"lb","note":"thinly sliced"},{"item":"red onion","qty":1,"unit":"medium"},{"item":"orange bell pepper","qty":1,"note":"strips"},{"item":"tomatoes","qty":2,"unit":"large","note":"wedges"},{"item":"ají amarillo","qty":1,"note":"seeded, in strips"},{"item":"garlic","qty":2,"unit":"clove","note":"minced"},{"item":"green onions","qty":0.33,"unit":"cup","note":"white part"},{"item":"corn kernels","qty":0.5,"unit":"cup"},{"item":"peas","qty":0.5,"unit":"cup"},{"item":"cilantro","qty":1,"unit":"tbsp"},{"item":"yellow potatoes","qty":6,"note":"peeled"},{"item":"vegetable oil","qty":3,"unit":"cup","note":"for frying"},{"item":"salt","qty":1,"unit":"tbsp","note":"for the fries"}]}'::jsonb),
('maricruzavalos-chilaquiles-rojos', 'Chilaquiles Rojos', 'Mexican', 'Maricruz Avalos Kitchen Blog', 'https://www.maricruzavalos.com/chilaquiles-rojos/', 40, 4, 2, 2, 2, 6, 44, array['tortillas', 'tomatoes', 'guajillo chile', 'queso fresco', 'mexican crema', 'eggs']::text[], '{"title":"Chilaquiles Rojos","cuisine":"Mexican","source":"Maricruz Avalos Kitchen Blog","url":"https://www.maricruzavalos.com/chilaquiles-rojos/","minutes":40,"servings":4,"key":["Corn tortillas","Tomatoes","Guajillo chiles","Queso fresco","Mexican crema","Eggs"],"minor":["Chiles de árbol","Onion","Garlic","Cumin seeds","Black peppercorns","Chicken bouillon","Vegetable oil","Olive oil","Salt"],"amounts":{"Corn tortillas":"12, cut in wedges","Tomatoes":"4 large","Guajillo chiles":"2, seeded","Queso fresco":"1 cup crumbled","Mexican crema":"1 cup","Eggs":"4, fried (optional)"},"steps":[["Simmer [[4]] tomatoes, [[2]] seeded guajillo chiles, [[3]] chiles de árbol and [[0.5]] onion in a little water for about 10 minutes.",10],["Blend them with [[1.5 cups]] water, [[1 clove]] garlic, [[0.25 tsp]] cumin seeds and [[0.5 tsp]] peppercorns until smooth.",null],["Heat [[0.67 cup]] vegetable oil and fry [[12]] tortilla wedges in batches until golden and crisp. Drain on paper towels.",10],["Heat [[2 tbsp]] olive oil in a clean pan. Add the sauce and [[2 tsp]] chicken bouillon and simmer 5 minutes until slightly thick. Add salt to taste.",5],["Add the chips and toss gently to coat. Cook about 1 minute.",1],["Serve topped with [[1 cup]] crema, [[1 cup]] queso fresco, [[0.5 cup]] chopped onion and a fried egg.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":640,"protein_g":20,"carbs_g":46,"fat_g":43},"video":null,"country":"MX","effort_steps":6,"ingredients":[{"item":"corn tortillas","qty":12,"note":"cut into wedges"},{"item":"vegetable oil","qty":0.67,"unit":"cup","note":"for frying"},{"item":"tomatoes","qty":4,"unit":"large"},{"item":"guajillo chiles","qty":2,"note":"stemmed and seeded"},{"item":"chiles de árbol","qty":3,"note":"optional"},{"item":"onion","qty":0.5,"unit":"medium"},{"item":"garlic","qty":1,"unit":"clove"},{"item":"cumin seeds","qty":0.25,"unit":"tsp"},{"item":"black peppercorns","qty":0.5,"unit":"tsp"},{"item":"chicken bouillon","qty":2,"unit":"tsp"},{"item":"olive oil","qty":2,"unit":"tbsp"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"},{"item":"queso fresco","qty":1,"unit":"cup"},{"item":"Mexican crema","qty":1,"unit":"cup"},{"item":"white onion","qty":0.5,"unit":"cup","note":"chopped"},{"item":"eggs","qty":4,"note":"fried, optional"}]}'::jsonb),
('savorysweetspoon-thit-kho-braised-pork-eggs', 'Thịt Kho (Vietnamese Braised Pork and Eggs)', 'Vietnamese', 'Savory Sweet Spoon', 'https://www.savorysweetspoon.com/wprm_print/thit-kho-vietnamese-braised-pork-and-eggs', 85, 6, 2, 2, 2, 8, 57, array['pork', 'eggs', 'coconut soda', 'fish sauce', 'shallot']::text[], '{"title":"Thịt Kho (Vietnamese Braised Pork and Eggs)","cuisine":"Vietnamese","source":"Savory Sweet Spoon","url":"https://www.savorysweetspoon.com/wprm_print/thit-kho-vietnamese-braised-pork-and-eggs","minutes":85,"servings":6,"key":["Pork belly","Eggs","Coconut soda","Fish sauce","Shallots"],"minor":["Sugar","Garlic","Soy sauce","Salt","Black pepper","Olive oil"],"amounts":{"Pork belly":"2 lb, in 1.5-inch cubes","Eggs":"8","Coconut soda":"3 cups","Fish sauce":"3 tbsp","Shallots":"2, finely diced"},"steps":[["Boil [[8]] eggs for about 10 minutes. Cool them in cold water and peel.",10],["Melt [[2 tbsp]] sugar in a small saucepan until golden brown, then carefully stir in [[3 tbsp]] water to make a caramel sauce.",5],["Boil [[2 lb]] cubed pork belly for 5 minutes to clean it, then drain.",5],["Mix the pork with [[1 tsp]] salt, [[0.5 tsp]] pepper, [[3 tbsp]] fish sauce, [[1 tbsp]] soy sauce and [[1.5 tbsp]] caramel sauce. Marinate 15 minutes.",null],["Heat [[0.5 tbsp]] oil in a pot and brown the pork in batches.",8],["Add [[2]] diced shallots and [[3 cloves]] minced garlic and cook 2 to 3 minutes.",3],["Pour in [[3 cups]] coconut soda and [[1 cup]] water. Bring to a simmer, cover and braise for about 40 minutes.",40],["Add the eggs for the last 10 minutes. Taste, adjust the seasoning and serve with rice.",10]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":690,"protein_g":26,"carbs_g":18,"fat_g":57},"video":null,"country":"VN","effort_steps":7,"ingredients":[{"item":"sugar","qty":2,"unit":"tbsp"},{"item":"water","qty":3,"unit":"tbsp","note":"for caramel"},{"item":"pork belly or shoulder","qty":2,"unit":"lb","note":"1.5-inch cubes"},{"item":"salt","qty":1,"unit":"tsp"},{"item":"ground black pepper","qty":0.5,"unit":"tsp"},{"item":"fish sauce","qty":3,"unit":"tbsp"},{"item":"soy sauce","qty":1,"unit":"tbsp"},{"item":"olive oil","qty":0.5,"unit":"tbsp"},{"item":"shallots","qty":2,"note":"finely diced"},{"item":"garlic","qty":3,"unit":"clove","note":"minced"},{"item":"coconut soda","qty":3,"unit":"cup"},{"item":"water","qty":1,"unit":"cup"},{"item":"eggs","qty":8,"note":"hard-boiled"}]}'::jsonb),
('falasteenifoodie-kabuli-pulao', 'Kabuli Pulao', 'Afghan', 'Falasteeni Foodie', 'https://falasteenifoodie.com/kabuli-pulao-afghanistans-national-dish/', 120, 4, 3, 3, 3, 8, 75, array['lamb', 'rice', 'carrots', 'raisin', 'onion', 'almond']::text[], '{"title":"Kabuli Pulao","cuisine":"Afghan","source":"Falasteeni Foodie","url":"https://falasteenifoodie.com/kabuli-pulao-afghanistans-national-dish/","minutes":120,"servings":4,"key":["Lamb shanks","Basmati rice","Carrots","Raisins","Onions","Almonds"],"minor":["Cumin seeds","Black cardamom","Green cardamom","Cinnamon sticks","Bay leaf","Cloves","Black peppercorns","Garlic","Ground cumin","Garam masala","Sugar","Neutral oil","Salt"],"amounts":{"Lamb shanks":"4 (or 2 lb bone-in lamb)","Basmati rice":"2 cups","Carrots":"3 large, in thin sticks","Raisins":"1/2 cup","Onions":"4 small-medium","Almonds":"1/4 cup sliced"},"steps":[["Heat [[3 tbsp]] oil in a large pot and cook [[2]] chopped onions until golden. Add [[4 cloves]] garlic, [[1 tbsp]] cumin seeds, [[2]] black and [[6]] green cardamom, [[2]] cinnamon sticks, [[1]] bay leaf, [[6]] cloves and [[1 tbsp]] peppercorns.",8],["Add [[4]] lamb shanks and brown them. Pour in [[7 cups]] water and [[1 tbsp]] salt and simmer 1.5 hours, until tender.",90],["Strain the broth and keep [[3 cups]] warm. Set the lamb aside.",null],["In a small pan cook [[3]] carrot sticks, [[0.5 cup]] raisins, [[2 tbsp]] sugar and [[0.25 cup]] almonds in [[2 tbsp]] oil until glossy. Wrap in foil.",6],["Wash [[2 cups]] basmati rice. In a large pot brown [[2]] sliced onions and [[1 tbsp]] cumin seeds in [[3 tbsp]] oil, then sear the lamb.",8],["Add the rice, [[1 tsp]] ground cumin, [[1 tsp]] garam masala and the warm broth. Bring to a boil.",null],["Set the foil packet on top of the rice, cover tightly and cook on low for 15 to 20 minutes without stirring.",18],["Spoon the rice onto a platter, place the lamb on top and scatter the carrot, raisin and nut topping over it.",null]],"technique":3,"prep":3,"precision":3,"nutrition":{"calories":880,"protein_g":48,"carbs_g":98,"fat_g":32},"video":null,"country":"AF","effort_steps":6,"ingredients":[{"item":"lamb shanks","qty":4},{"item":"cumin seeds","qty":2,"unit":"tbsp","note":"divided"},{"item":"black cardamom pods","qty":2},{"item":"green cardamom pods","qty":6},{"item":"cinnamon sticks","qty":2},{"item":"bay leaf","qty":1},{"item":"whole cloves","qty":6},{"item":"black peppercorns","qty":1,"unit":"tbsp"},{"item":"yellow onions","qty":4,"note":"2 chopped, 2 sliced"},{"item":"garlic","qty":4,"unit":"clove","note":"minced"},{"item":"neutral oil","qty":8,"unit":"tbsp","note":"divided"},{"item":"salt","qty":1,"unit":"tbsp"},{"item":"water","qty":7,"unit":"cup"},{"item":"basmati rice","qty":2,"unit":"cup","note":"washed"},{"item":"ground cumin","qty":1,"unit":"tsp"},{"item":"garam masala","qty":1,"unit":"tsp"},{"item":"carrots","qty":3,"unit":"large","note":"thin sticks"},{"item":"raisins","qty":0.5,"unit":"cup"},{"item":"sugar","qty":2,"unit":"tbsp"},{"item":"sliced almonds or pistachios","qty":0.25,"unit":"cup"}]}'::jsonb),
('aspicyperspective-steak-au-poivre-cognac-cream', 'Steak au Poivre with Cognac Cream', 'French', 'A Spicy Perspective', 'https://www.aspicyperspective.com/steak-au-poivre-pepper-steak-recipe-with-cognac-cream-sauce/', 35, 4, 4, 2, 4, 7, 61, array['beef', 'black peppercorn', 'cognac', 'cream']::text[], '{"title":"Steak au Poivre with Cognac Cream","cuisine":"French","source":"A Spicy Perspective","url":"https://www.aspicyperspective.com/steak-au-poivre-pepper-steak-recipe-with-cognac-cream-sauce/","minutes":35,"servings":4,"key":["Beef tenderloin steaks","Black peppercorns","Cognac","Heavy cream"],"minor":["Olive oil","Butter","Garlic","Dried thyme","Beef base","Salt"],"amounts":{"Beef tenderloin steaks":"4 (8 oz each), 1.5-2 in thick","Black peppercorns":"1/4 cup","Cognac":"3/4 cup","Heavy cream":"1 1/4 cups"},"steps":[["Take [[4]] tenderloin steaks out of the fridge 30 minutes before cooking and salt them well.",null],["Coarsely crack [[0.25 cup]] peppercorns and press them firmly into both sides of the steaks.",null],["Heat [[1 tbsp]] olive oil and [[1 tbsp]] butter in a cast-iron skillet over medium heat. Sear the steaks 4 to 5 minutes per side.",10],["Move the steaks to a plate and cover with foil.",null],["Off the heat, pour [[0.5 cup]] cognac into the skillet, then return to the heat and let the alcohol cook off.",1],["Add [[1.25 cups]] heavy cream, [[1 clove]] minced garlic, [[1 tsp]] dried thyme and [[0.5 tsp]] beef base. Simmer 4 to 5 minutes until slightly thick.",5],["Stir in [[2 tbsp]] more cognac and season with salt. Spoon the sauce over the steaks and serve.",null]],"technique":4,"prep":2,"precision":4,"nutrition":{"calories":720,"protein_g":48,"carbs_g":6,"fat_g":46},"video":null,"country":"FR","effort_steps":7,"ingredients":[{"item":"beef tenderloin steaks","qty":4,"note":"8 oz each"},{"item":"black peppercorns","qty":0.25,"unit":"cup","note":"coarsely cracked"},{"item":"olive oil","qty":1,"unit":"tbsp"},{"item":"butter","qty":1,"unit":"tbsp"},{"item":"cognac","qty":0.75,"unit":"cup","note":"divided"},{"item":"heavy cream","qty":1.25,"unit":"cup"},{"item":"garlic","qty":1,"unit":"clove","note":"minced"},{"item":"dried thyme","qty":1,"unit":"tsp"},{"item":"beef base","qty":0.5,"unit":"tsp"},{"item":"salt","qty":1,"unit":"tsp","note":"to taste"}]}'::jsonb),
('chefshop-lobster-mac-and-cheese', 'Lobster Mac and Cheese', 'American', 'ChefShop', 'https://chefshop.com/blogs/recipes/lobster-mac-and-cheese-recipe', 45, 6, 2, 3, 2, 7, 48, array['lobster', 'pasta', 'cream', 'gruyre', 'cheddar', 'parmesan']::text[], '{"title":"Lobster Mac and Cheese","cuisine":"American","source":"ChefShop","url":"https://chefshop.com/blogs/recipes/lobster-mac-and-cheese-recipe","minutes":45,"servings":6,"key":["Lobster","Pasta","Heavy cream","Gruyère","Monterey Jack","Parmigiano-Reggiano"],"minor":["Chives","Parsley","Sea salt","Panko breadcrumbs"],"amounts":{"Lobster":"2 whole, boiled, meat chopped","Pasta":"1 1/2 lb farfalle or fusilli","Heavy cream":"2 cups","Gruyère":"1/2 cup grated","Monterey Jack":"1/2 cup grated","Parmigiano-Reggiano":"1/2 cup grated"},"steps":[["Heat the oven to 350°F (175°C).",null],["Boil [[1.5 lb]] pasta in well-salted water until done. Drain, rinse and put it in a large bowl.",10],["Pick the meat from [[2]] cooked lobsters and roughly chop it.",null],["Bring [[2 cups]] heavy cream to a boil in a large saucepan.",null],["Stir in [[0.5 cup]] Gruyère, [[0.5 cup]] Monterey Jack, [[0.5 cup]] Parmigiano, [[1 tbsp]] chives, [[1 tbsp]] parsley, the lobster and salt until the cheese melts.",3],["Pour the sauce over the pasta and stir to coat.",null],["Spread in a 3-quart baking dish, top with [[0.5 cup]] panko and bake about 15 minutes, until bubbling.",15]],"technique":2,"prep":3,"precision":2,"nutrition":{"calories":850,"protein_g":38,"carbs_g":88,"fat_g":38},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"farfalle or fusilli pasta","qty":1.5,"unit":"lb"},{"item":"heavy cream","qty":2,"unit":"cup"},{"item":"Gruyère","qty":0.5,"unit":"cup","note":"grated"},{"item":"Monterey Jack","qty":0.5,"unit":"cup","note":"grated"},{"item":"Parmigiano-Reggiano","qty":0.5,"unit":"cup","note":"grated"},{"item":"fresh chives","qty":1,"unit":"tbsp","note":"chopped"},{"item":"fresh parsley","qty":1,"unit":"tbsp","note":"chopped"},{"item":"lobsters","qty":2,"note":"boiled, meat chopped"},{"item":"sea salt","qty":1,"unit":"pinch","note":"to taste"},{"item":"panko breadcrumbs","qty":0.5,"unit":"cup"}]}'::jsonb),
('rasamalaysia-shrimp-scampi-linguine', 'Shrimp Scampi with Linguine', 'Italian-American', 'Rasa Malaysia', 'https://rasamalaysia.com/shrimp-scampi-linguine/', 20, 4, 2, 2, 2, 6, 39, array['pasta', 'shrimp', 'butter', 'garlic', 'white wine']::text[], '{"title":"Shrimp Scampi with Linguine","cuisine":"Italian-American","source":"Rasa Malaysia","url":"https://rasamalaysia.com/shrimp-scampi-linguine/","minutes":20,"servings":4,"key":["Linguine","Shrimp","Butter","Garlic","White wine"],"minor":["Cayenne pepper","Olive oil","Salt","Sugar","Cherry tomatoes","Lemon juice","Black pepper","Italian parsley","Parmigiano-Reggiano"],"amounts":{"Linguine":"12 oz (4 servings)","Shrimp":"1 lb, peeled and deveined","Butter":"2 oz unsalted","Garlic":"5 cloves, minced","White wine":"5 tbsp"},"steps":[["Cook [[12 oz]] linguine in boiling salted water following the package directions. Drain.",10],["Sprinkle [[0.25 tsp]] cayenne over [[1 lb]] peeled shrimp.",null],["Melt [[2 oz]] butter in a large pan, add [[1.5 tbsp]] olive oil and cook [[5 cloves]] minced garlic until fragrant.",1],["Add the shrimp and cook until they start to turn pink.",2],["Pour in [[5 tbsp]] white wine and add salt and [[0.25 tsp]] sugar. Add [[6]] halved cherry tomatoes and the linguine and toss.",1],["When the shrimp are cooked through, add a squeeze of lemon juice, [[0.5 tsp]] black pepper and [[1 tbsp]] chopped parsley. Toss and serve with shaved Parmigiano.",null]],"technique":2,"prep":2,"precision":2,"nutrition":{"calories":560,"protein_g":33,"carbs_g":66,"fat_g":17},"video":null,"country":"US","effort_steps":6,"ingredients":[{"item":"linguine","qty":12,"unit":"oz"},{"item":"shrimp","qty":1,"unit":"lb","note":"peeled and deveined"},{"item":"cayenne pepper","qty":0.25,"unit":"tsp"},{"item":"unsalted butter","qty":2,"unit":"oz"},{"item":"olive oil","qty":1.5,"unit":"tbsp"},{"item":"garlic","qty":5,"unit":"clove","note":"minced"},{"item":"white wine","qty":5,"unit":"tbsp"},{"item":"salt","qty":1,"unit":"pinch","note":"to taste"},{"item":"sugar","qty":0.25,"unit":"tsp"},{"item":"cherry tomatoes","qty":6,"note":"halved"},{"item":"lemon juice","qty":1,"unit":"tbsp"},{"item":"black pepper","qty":0.5,"unit":"tsp"},{"item":"Italian parsley","qty":1,"unit":"tbsp","note":"chopped"},{"item":"Parmigiano-Reggiano","qty":1,"unit":"oz","note":"shaved"}]}'::jsonb)
